//     {
//         if (holdArrow == ARROW_NORM)
//         {
//             draw_sprite(sArrowRight, -1, x+4, y+1);
//         }
//         else if (holdArrow == ARROW_BOMB)
//         {
//             if (holdArrowToggle) draw_sprite(sBombArrowRight, 0, x+4, y+2);
//             else draw_sprite(sBombArrowRight, 1, x+4, y+2);
//         }
//     }
//     else if (facing == LEFT)
//     {
//         if (holdArrow == ARROW_NORM)
//         {
//             draw_sprite(sArrowLeft, -1, x-4, y+1);
//         }
//         else if (holdArrow == ARROW_BOMB)
//         {
//             if (holdArrowToggle) draw_sprite(sBombArrowLeft, 0, x-4, y+2);
//             else draw_sprite(sBombArrowLeft, 1, x-4, y+2);
//         }
//     }
// }
// /*
// if canRun
// {
//   xOffset=80
//   if player=1
//     yOffset=120
//   else
//     yOffset=143
//   //draw the "flySpeed" bar, which shows how much speed the character has acquired while holding the global.Run button
//   //draw_healthbar(view_xview[0]+224+xOffset,view_yview[0]+432+yOffset,view_xview[0]+400+xOffset,view_yview[0]+450+yOffset,flySpeed,make_color_rgb(0,64,128),c_blue,c_aqua,0,1,1)
// }
// */
//
function gml_Script_characterDrawEvent(_inst, _other) {
    _inst.gmldraw = 1 ? 1 : 0;
    if (_inst.gmlfacing == _inst.gmlRIGHT) {
        _inst.setxscale(-1);
    } else {
        _inst.setxscale(1);
    }
    if (_inst.gmlblinkToggle != 1) {
        {
            if ((_inst.gmlstate == _inst.gmlCLIMBING || _inst.sprite_index == 188 || _inst.sprite_index == 230 || _inst.sprite_index == 245) && global.gmlhasJetpack > 0.5 && !(_inst.gmlwhipping > 0.5)) {
                {
                    draw_sprite_ext(_inst, _inst.sprite_index, -1, _inst.x, _inst.y, _inst.image_xscale, _inst.image_yscale, _inst.image_angle, _inst.get_imageblend(), _inst.image_alpha);
                    draw_sprite(_inst, 540, -1, _inst.x, _inst.y);
                    _inst.gmldraw = 0 ? 1 : 0;
                }
            } else {
                if (global.gmlhasJetpack > 0.5 && _inst.gmlfacing == _inst.gmlRIGHT) {
                    draw_sprite(_inst, 538, -1, _inst.x - 4, _inst.y - 1);
                } else {
                    if (global.gmlhasJetpack > 0.5) {
                        draw_sprite(_inst, 539, -1, _inst.x + 4, _inst.y - 1);
                    }
                }
            }
            if (_inst.gmldraw > 0.5) {
                {
                    if (_inst.gmlredColor > 0) {
                        draw_sprite_ext(_inst, _inst.sprite_index, -1, _inst.x, _inst.y, _inst.image_xscale, _inst.image_yscale, _inst.image_angle, make_color_rgb(200 + _inst.gmlredColor, 0, 0), _inst.image_alpha);
                    } else {
                        draw_sprite_ext(_inst, _inst.sprite_index, -1, _inst.x, _inst.y, _inst.image_xscale, _inst.image_yscale, _inst.image_angle, _inst.get_imageblend(), _inst.image_alpha);
                    }
                }
            }
            if (_inst.gmlfacing == _inst.gmlRIGHT) {
                {
                    if (_inst.gmlholdArrow == _inst.gmlARROW_NORM) {
                        {
                            draw_sprite(_inst, 579, -1, _inst.x + 4, _inst.y + 1);
                        }
                    } else {
                        if (_inst.gmlholdArrow == _inst.gmlARROW_BOMB) {
                            {
                                if (_inst.gmlholdArrowToggle > 0.5) {
                                    draw_sprite(_inst, 580, 0, _inst.x + 4, _inst.y + 2);
                                } else {
                                    draw_sprite(_inst, 580, 1, _inst.x + 4, _inst.y + 2);
                                }
                            }
                        }
                    }
                }
            } else {
                if (_inst.gmlfacing == _inst.gmlLEFT) {
                    {
                        if (_inst.gmlholdArrow == _inst.gmlARROW_NORM) {
                            {
                                draw_sprite(_inst, 578, -1, _inst.x - 4, _inst.y + 1);
                            }
                        } else {
                            if (_inst.gmlholdArrow == _inst.gmlARROW_BOMB) {
                                {
                                    if (_inst.gmlholdArrowToggle > 0.5) {
                                        draw_sprite(_inst, 581, 0, _inst.x - 4, _inst.y + 2);
                                    } else {
                                        draw_sprite(_inst, 581, 1, _inst.x - 4, _inst.y + 2);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

