function gml_Script_characterSprite(_inst, _other) {
    if (global.gmlisTunnelMan > 0.5 && !(_inst.gmlstunned > 0.5) && !(_inst.gmlwhipping > 0.5)) {
        {
            if (_inst.gmlstate == _inst.gmlSTANDING) {
                {
                    if (!(collision_point(_inst, _inst.x - 2, _inst.y + 9, 8, 0, 0) > 0.5)) {
                        {
                            _inst.image_speed = 0.6;
                            _inst.set_sprite_index(235);
                        }
                    } else {
                        _inst.set_sprite_index(232);
                    }
                }
            }
            if (_inst.gmlstate == _inst.gmlRUNNING) {
                {
                    if (_inst.gmlkUp > 0.5) {
                        _inst.set_sprite_index(238);
                    } else {
                        _inst.set_sprite_index(236);
                    }
                }
            }
            if (_inst.gmlstate == _inst.gmlDUCKING) {
                {
                    if (_inst.gmlxVel == 0) {
                        _inst.set_sprite_index(239);
                    } else {
                        if (abs(_inst.gmlxVel) < 3) {
                            _inst.set_sprite_index(243);
                        } else {
                            _inst.set_sprite_index(236);
                        }
                    }
                }
            }
            if (_inst.gmlstate == _inst.gmlLOOKING_UP) {
                {
                    if (abs(_inst.gmlxVel) > 0) {
                        _inst.set_sprite_index(236);
                    } else {
                        _inst.set_sprite_index(233);
                    }
                }
            }
            if (_inst.gmlstate == _inst.gmlJUMPING) {
                _inst.set_sprite_index(249);
            }
            if (_inst.gmlstate == _inst.gmlFALLING && _inst.gmlstatePrev == _inst.gmlFALLING && _inst.gmlstatePrevPrev == _inst.gmlFALLING) {
                _inst.set_sprite_index(244);
            }
            if (_inst.gmlstate == _inst.gmlHANGING) {
                _inst.set_sprite_index(237);
            }
            if (_inst.gmlpushTimer > 20) {
                _inst.set_sprite_index(234);
            }
            if (_inst.gmlstate == _inst.gmlDUCKTOHANG) {
                _inst.set_sprite_index(242);
            }
            if (_inst.gmlstate == _inst.gmlCLIMBING) {
                {
                    if (collision_point(_inst, _inst.x, _inst.y, 58, 0, 0) > 0.5) {
                        {
                            if (_inst.gmlkDown > 0.5) {
                                _inst.set_sprite_index(248);
                            } else {
                                _inst.set_sprite_index(247);
                            }
                        }
                    } else {
                        _inst.set_sprite_index(246);
                    }
                }
            }
        }
    } else {
        if (global.gmlisDamsel > 0.5 && !(_inst.gmlstunned > 0.5) && !(_inst.gmlwhipping > 0.5)) {
            {
                if (_inst.gmlstate == _inst.gmlSTANDING) {
                    {
                        if (!(collision_point(_inst, _inst.x - 2, _inst.y + 9, 8, 0, 0) > 0.5)) {
                            {
                                _inst.image_speed = 0.6;
                                _inst.set_sprite_index(212);
                            }
                        } else {
                            _inst.set_sprite_index(210);
                        }
                    }
                }
                if (_inst.gmlstate == _inst.gmlRUNNING) {
                    {
                        if (_inst.gmlkUp > 0.5) {
                            _inst.set_sprite_index(215);
                        } else {
                            _inst.set_sprite_index(215);
                        }
                    }
                }
                if (_inst.gmlstate == _inst.gmlDUCKING) {
                    {
                        if (_inst.gmlxVel == 0) {
                            _inst.set_sprite_index(217);
                        } else {
                            if (abs(_inst.gmlxVel) < 3) {
                                _inst.set_sprite_index(218);
                            } else {
                                _inst.set_sprite_index(215);
                            }
                        }
                    }
                }
                if (_inst.gmlstate == _inst.gmlLOOKING_UP) {
                    {
                        if (abs(_inst.gmlxVel) > 0) {
                            _inst.set_sprite_index(215);
                        } else {
                            _inst.set_sprite_index(213);
                        }
                    }
                }
                if (_inst.gmlstate == _inst.gmlJUMPING) {
                    _inst.set_sprite_index(225);
                }
                if (_inst.gmlstate == _inst.gmlFALLING && _inst.gmlstatePrev == _inst.gmlFALLING && _inst.gmlstatePrevPrev == _inst.gmlFALLING) {
                    _inst.set_sprite_index(227);
                }
                if (_inst.gmlstate == _inst.gmlHANGING) {
                    _inst.set_sprite_index(220);
                }
                if (_inst.gmlpushTimer > 20) {
                    _inst.set_sprite_index(214);
                }
                if (_inst.gmlstate == _inst.gmlDUCKTOHANG) {
                    _inst.set_sprite_index(219);
                }
                if (_inst.gmlstate == _inst.gmlCLIMBING) {
                    {
                        if (collision_point(_inst, _inst.x, _inst.y, 58, 0, 0) > 0.5) {
                            {
                                if (_inst.gmlkDown > 0.5) {
                                    _inst.set_sprite_index(223);
                                } else {
                                    _inst.set_sprite_index(222);
                                }
                            }
                        } else {
                            _inst.set_sprite_index(221);
                        }
                    }
                }
            }
        } else {
            if (!(_inst.gmlstunned > 0.5) && !(_inst.gmlwhipping > 0.5)) {
                {
                    if (_inst.gmlstate == _inst.gmlSTANDING) {
                        {
                            if (!(collision_point(_inst, _inst.x - 2, _inst.y + 9, 8, 0, 0) > 0.5)) {
                                {
                                    _inst.image_speed = 0.6;
                                    _inst.set_sprite_index(178);
                                }
                            } else {
                                _inst.set_sprite_index(175);
                            }
                        }
                    }
                    if (_inst.gmlstate == _inst.gmlRUNNING) {
                        {
                            if (_inst.gmlkUp > 0.5) {
                                _inst.set_sprite_index(180);
                            } else {
                                _inst.set_sprite_index(179);
                            }
                        }
                    }
                    if (_inst.gmlstate == _inst.gmlDUCKING) {
                        {
                            if (_inst.gmlxVel == 0) {
                                _inst.set_sprite_index(181);
                            } else {
                                if (abs(_inst.gmlxVel) < 3) {
                                    _inst.set_sprite_index(182);
                                } else {
                                    _inst.set_sprite_index(179);
                                }
                            }
                        }
                    }
                    if (_inst.gmlstate == _inst.gmlLOOKING_UP) {
                        {
                            if (abs(_inst.gmlxVel) > 0) {
                                _inst.set_sprite_index(180);
                            } else {
                                _inst.set_sprite_index(184);
                            }
                        }
                    }
                    if (_inst.gmlstate == _inst.gmlJUMPING) {
                        _inst.set_sprite_index(189);
                    }
                    if (_inst.gmlstate == _inst.gmlFALLING && _inst.gmlstatePrev == _inst.gmlFALLING && _inst.gmlstatePrevPrev == _inst.gmlFALLING) {
                        _inst.set_sprite_index(191);
                    }
                    if (_inst.gmlstate == _inst.gmlHANGING) {
                        _inst.set_sprite_index(190);
                    }
                    if (_inst.gmlpushTimer > 20) {
                        _inst.set_sprite_index(177);
                    }
                    if (_inst.gmlstate == _inst.gmlCLIMBING) {
                        {
                            if (collision_point(_inst, _inst.x, _inst.y, 58, 0, 0) > 0.5) {
                                {
                                    if (_inst.gmlkDown > 0.5) {
                                        _inst.set_sprite_index(187);
                                    } else {
                                        _inst.set_sprite_index(186);
                                    }
                                }
                            } else {
                                _inst.set_sprite_index(185);
                            }
                        }
                    }
                    if (_inst.gmlstate == _inst.gmlDUCKTOHANG) {
                        _inst.set_sprite_index(183);
                    }
                }
            }
        }
    }
}

// #####################################################################################################
// /*
// Makes the object "active." An "active" object is one that has the variables
// xVel, yVel, xAcc, and yAcc.
// */
// xVel=0
// yVel=0
// xAcc=0
// yAcc=0
//
function gml_Script_makeActive(_inst, _other) {
    _inst.gmlxVel = 0;
    _inst.gmlyVel = 0;
    _inst.gmlxAcc = 0;
    _inst.gmlyAcc = 0;
}

// #####################################################################################################
// /*
// Returns whether a GENERAL trait about a character is true.
// Only the platform character should run this script.
//
// argument0 can be one of the following:
// ON_GROUND
// IN_AIR
// ON_LADDER
//
// Example of usage:
// Event: oCharacter collides with oGoomba
// Action: if platformCharacterIs(ON_GROUND) instance_destroy()
// */
//
// if (argument0=ON_GROUND) and (state=RUNNING or state=STANDING or state=DUCKING or state=LOOKING_UP)
//   return 1
// if (argument0=IN_AIR) and (state=JUMPING or state=FALLING)
//   return 1
// if (argument0=ON_LADDER) and (state=CLIMBING)
//   return 1
// return 0
//
function gml_Script_platformCharacterIs(_inst, _other, argument0) {
    if (argument0 == _inst.gmlON_GROUND && (_inst.gmlstate == _inst.gmlRUNNING || _inst.gmlstate == _inst.gmlSTANDING || _inst.gmlstate == _inst.gmlDUCKING || _inst.gmlstate == _inst.gmlLOOKING_UP)) {
        return 1;
    }
    if (argument0 == _inst.gmlIN_AIR && (_inst.gmlstate == _inst.gmlJUMPING || _inst.gmlstate == _inst.gmlFALLING)) {
        return 1;
    }
    if (argument0 == _inst.gmlON_LADDER && _inst.gmlstate == _inst.gmlCLIMBING) {
        return 1;
    }
    return 0;
}

