//
// if (sprite_index == sDuckLeft or
//     sprite_index == sCrawlLeft or
//     sprite_index == sDamselDuckL or
//     sprite_index == sDamselCrawlL or
//     sprite_index == sTunnelDuckL or
//     sprite_index == sTunnelCrawlL)
// {
//     return true;
// }
// else return false;
//
function gml_Script_scrPlayerIsDucking(_inst, _other) {
    if (_inst.sprite_index == 181 || _inst.sprite_index == 182 || _inst.sprite_index == 217 || _inst.sprite_index == 218 || _inst.sprite_index == 239 || _inst.sprite_index == 243) {
        {
            return 1;
        }
    } else {
        return 0;
    }
}

