//
function gml_Script_scrHoldItem(_inst, _other, argument0) {
    _inst.gmlitemType = argument0;
    _inst.gmlpickup = 1 ? 1 : 0;
    if (_inst.gmlitemType == "") {
        {
            _inst.gmlholdItem = 0;
            _inst.gmlpickupItemType = "";
        }
    } else {
        {
            if (_inst.gmlitemType == "Rock") {
                _inst.gmlholdItem = instance_create(_inst.x, _inst.y, 72);
            } else {
                if (_inst.gmlitemType == "Jar") {
                    _inst.gmlholdItem = instance_create(_inst.x, _inst.y, 84);
                } else {
                    if (_inst.gmlitemType == "Skull") {
                        _inst.gmlholdItem = instance_create(_inst.x, _inst.y, 85);
                    } else {
                        if (_inst.gmlitemType == "Fish Bone") {
                            _inst.gmlholdItem = instance_create(_inst.x, _inst.y, 87);
                        } else {
                            if (_inst.gmlitemType == "Arrow") {
                                _inst.gmlholdItem = instance_create(_inst.x, _inst.y, 86);
                            } else {
                                if (_inst.gmlitemType == "Rock") {
                                    _inst.gmlholdItem = instance_create(_inst.x, _inst.y, 72);
                                } else {
                                    if (_inst.gmlitemType == "Machete") {
                                        _inst.gmlholdItem = instance_create(_inst.x, _inst.y, 81);
                                    } else {
                                        if (_inst.gmlitemType == "Mattock") {
                                            _inst.gmlholdItem = instance_create(_inst.x, _inst.y, 83);
                                        } else {
                                            if (_inst.gmlitemType == "Mattock Head") {
                                                _inst.gmlholdItem = instance_create(_inst.x, _inst.y, 74);
                                            } else {
                                                if (_inst.gmlitemType == "Pistol") {
                                                    _inst.gmlholdItem = instance_create(_inst.x, _inst.y, 77);
                                                } else {
                                                    if (_inst.gmlitemType == "Web Cannon") {
                                                        _inst.gmlholdItem = instance_create(_inst.x, _inst.y, 78);
                                                    } else {
                                                        if (_inst.gmlitemType == "Teleporter") {
                                                            _inst.gmlholdItem = instance_create(_inst.x, _inst.y, 79);
                                                        } else {
                                                            if (_inst.gmlitemType == "Shotgun") {
                                                                _inst.gmlholdItem = instance_create(_inst.x, _inst.y, 76);
                                                            } else {
                                                                if (_inst.gmlitemType == "Bow") {
                                                                    _inst.gmlholdItem = instance_create(_inst.x, _inst.y, 80);
                                                                } else {
                                                                    if (_inst.gmlitemType == "Flare") {
                                                                        _inst.gmlholdItem = instance_create(_inst.x, _inst.y, 88);
                                                                    } else {
                                                                        if (_inst.gmlitemType == "Sceptre") {
                                                                            _inst.gmlholdItem = instance_create(_inst.x, _inst.y, 82);
                                                                        } else {
                                                                            if (_inst.gmlitemType == "Key") {
                                                                                _inst.gmlholdItem = instance_create(_inst.x, _inst.y, 159);
                                                                            } else {
                                                                                _inst.gmlpickup = 0 ? 1 : 0;
                                                                            }
                                                                        }
                                                                    }
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            if (_inst.gmlpickup > 0.5) {
                {
                    yyInst(_inst.gmlholdItem).gmlheld = 1 ? 1 : 0;
                    yyInst(_inst.gmlholdItem).gmlcost = 0;
                    yyInst(_inst.gmlholdItem).gmlnew = 0 ? 1 : 0;
                    _inst.gmlpickupItemType = _inst.gmlitemType;
                    _inst.gmlwhoaTimer = _inst.gmlwhoaTimerMax;
                }
            } else {
                {
                    _inst.gmlholdItem = 0;
                    _inst.gmlpickupItemType = "";
                }
            }
        }
    }
}

