//
// ***********************************************************************************/
//
// if (!holdItem) return 0;
//
// holdItem.held = false;
//
// holdItem.xVel = argument0;
// holdItem.yVel = argument1;
//
// if (bowArmed)
// {
//     scrFireBow();
// }
//
// if (pickupItemType != holdItem.type)
// {
//     scrHoldItem(pickupItemType);
// }
// else
// {
//     holdItem = 0;
//     pickupItemType = "";
// }
//
function gml_Script_scrDropItem(_inst, _other, argument0, argument1) {
    if (!(_inst.gmlholdItem > 0.5)) {
        return 0;
    }
    yyInst(_inst.gmlholdItem).gmlheld = 0 ? 1 : 0;
    yyInst(_inst.gmlholdItem).gmlxVel = argument0;
    yyInst(_inst.gmlholdItem).gmlyVel = argument1;
    if (_inst.gmlbowArmed > 0.5) {
        {
            gml_Script_scrFireBow(_inst, _other);
        }
    }
    if (_inst.gmlpickupItemType != yyInst(_inst.gmlholdItem).gmltype) {
        {
            gml_Script_scrHoldItem(_inst, _other, _inst.gmlpickupItemType);
        }
    } else {
        {
            _inst.gmlholdItem = 0;
            _inst.gmlpickupItemType = "";
        }
    }
}

