//     but WITHOUT WARRANTY.  Please see the Spelunky User License for more details.
//
//     The Spelunky User License should be available in "Game Information", which
//     can be found in the Resource Explorer, or as an external file called COPYING.
//     If not, please obtain a new copy of Spelunky from <http://spelunkyworld.com/>
//
// ***********************************************************************************/
//
// tx = argument0;
//
// if (tx < 160+16) return 0;
// else if (tx >= 160+16 and tx < 320+16) return 1;
// else if (tx >= 320+16 and tx < 480+16) return 2;
// else if (tx >= 480+16) return 3;
//
// return -1;
//
function gml_Script_scrGetRoomX(_inst, _other, argument0) {
    _inst.gmltx = argument0;
    if (_inst.gmltx < 176) {
        return 0;
    } else {
        if (_inst.gmltx >= 176 && _inst.gmltx < 336) {
            return 1;
        } else {
            if (_inst.gmltx >= 336 && _inst.gmltx < 496) {
                return 2;
            } else {
                if (_inst.gmltx >= 496) {
                    return 3;
                }
            }
        }
    }
    return -1;
}

// #####################################################################################################
// //
// // scrGetRoomY(y)
// //
// // Returns the vertical room number of a room given the y-coord.
// //
