//     You can redistribute and/or modify Spelunky, including its source code, under
//     the terms of the Spelunky User License.
//
//     Spelunky is distributed in the hope that it will be entertaining and useful,
//     but WITHOUT WARRANTY.  Please see the Spelunky User License for more details.
//
//     The Spelunky User License should be available in "Game Information", which
//     can be found in the Resource Explorer, or as an external file called COPYING.
//     If not, please obtain a new copy of Spelunky from <http://spelunkyworld.com/>
//
// ***********************************************************************************/
//
// ty = argument0;
//
// if (ty < 128+16) return 0;
// else if (ty >= 128+16 and ty < 256+16) return 1;
// else if (ty >= 256+16 and ty < 384+16) return 2;
// else if (ty >= 384+16 and ty < 512+16) return 3;
// else if (ty >= 512+16) return 4;
//
// return -1;
//
function gml_Script_scrGetRoomY(_inst, _other, argument0) {
    _inst.gmlty = argument0;
    if (_inst.gmlty < 144) {
        return 0;
    } else {
        if (_inst.gmlty >= 144 && _inst.gmlty < 272) {
            return 1;
        } else {
            if (_inst.gmlty >= 272 && _inst.gmlty < 400) {
                return 2;
            } else {
                if (_inst.gmlty >= 400 && _inst.gmlty < 528) {
                    return 3;
                } else {
                    if (_inst.gmlty >= 528) {
                        return 4;
                    }
                }
            }
        }
    }
    return -1;
}

