// //
// // scrShopkeeperAnger(message)
// //
// // Make the nearest shopkeeper angry.  RAWR!
// //
//
// shp = instance_nearest(x, y, oShopkeeper);
// if (shp)
// {
//     if (not shp.dead and not shp.angered)
//     {
//         shp.status = 2;
//         if (global.murderer) global.message = tr("YOU'LL PAY FOR YOUR CRIMES!");
//         else if (argument0 == 0) global.message = tr("COME BACK HERE, THIEF!");
//         else if (argument0 == 1) global.message = tr("DIE, YOU VANDAL!");
//         else if (argument0 == 2) global.message = tr("TERRORIST!");
//         else if (argument0 == 3) global.message = tr("HEY, ONLY I CAN DO THAT!");
//         else global.message = tr("NOW I'M REALLY STEAMED!");
//         global.message2 = "";
//         global.messageTimer = 80;
//         if (global.thiefLevel > 0) global.thiefLevel += 3;
//         else global.thiefLevel += 2;
//     }
// }
//
function gml_Script_scrShopkeeperAnger(_inst, _other, argument0) {
    _inst.gmlshp = instance_nearest(_inst, _inst.x, _inst.y, 341);
    if (_inst.gmlshp > 0.5) {
        {
            if (!(yyInst(_inst.gmlshp).gmldead > 0.5) && !(yyInst(_inst.gmlshp).gmlangered > 0.5)) {
                {
                    yyInst(_inst.gmlshp).gmlstatus = 2;
                    if (global.gmlmurderer > 0.5) {
                        global.gmlmessage = gml_Script_tr(_inst, _other, "YOU'LL PAY FOR YOUR CRIMES!");
                    } else {
                        if (argument0 == 0) {
                            global.gmlmessage = gml_Script_tr(_inst, _other, "COME BACK HERE, THIEF!");
                        } else {
                            if (argument0 == 1) {
                                global.gmlmessage = gml_Script_tr(_inst, _other, "DIE, YOU VANDAL!");
                            } else {
                                if (argument0 == 2) {
                                    global.gmlmessage = gml_Script_tr(_inst, _other, "TERRORIST!");
                                } else {
                                    if (argument0 == 3) {
                                        global.gmlmessage = gml_Script_tr(_inst, _other, "HEY, ONLY I CAN DO THAT!");
                                    } else {
                                        global.gmlmessage = gml_Script_tr(_inst, _other, "NOW I'M REALLY STEAMED!");
                                    }
                                }
                            }
                        }
                    }
                    global.gmlmessage2 = "";
                    global.gmlmessageTimer = 80;
                    if (global.gmlthiefLevel > 0) {
                        global.gmlthiefLevel += 3;
                    } else {
                        global.gmlthiefLevel += 2;
                    }
                }
            }
        }
    }
}

