// //
//
// if (room_get_name(room) == argument0) return true;
// else if argument0="rTutorial" && room=rTutorial return true;
// else return false;
//
function gml_Script_isRoom(_inst, _other, argument0) {
    if (room_get_name(g_pBuiltIn.get_current_room()) == argument0) {
        return 1;
    } else {
        if (argument0 == "rTutorial" && g_pBuiltIn.get_current_room() == 10) {
            return 1;
        } else {
            return 0;
        }
    }
}

// #####################################################################################################
// //
// // isLevel()
// //
// // Checks if you are in a level.
// //
//
// if (isRoom("rTutorial") or isRoom("rLoadLevel") or isRoom("rLevel") or isRoom("rLevel2") or isRoom("rLevel3") or isRoom("rOlmec")) return true;
// return false
//
function gml_Script_isLevel(_inst, _other) {
    if (
        gml_Script_isRoom(_inst, _other, "rTutorial") > 0.5 ||
        gml_Script_isRoom(_inst, _other, "rLoadLevel") > 0.5 ||
        gml_Script_isRoom(_inst, _other, "rLevel") > 0.5 ||
        gml_Script_isRoom(_inst, _other, "rLevel2") > 0.5 ||
        gml_Script_isRoom(_inst, _other, "rLevel3") > 0.5 ||
        gml_Script_isRoom(_inst, _other, "rOlmec") > 0.5
    ) {
        return 1;
    }
    return 0;
}

// #####################################################################################################
// //
// // isRealLevel()
// //
// // Checks if you are in a non-custom level.  (Only used for stat-checking atm.)
// //
//
// if (isRoom("rLevel") or isRoom("rLevel2") or isRoom("rLevel3") or isRoom("rOlmec")) return true;
// return false
//
function gml_Script_isRealLevel(_inst, _other) {
    if (gml_Script_isRoom(_inst, _other, "rLevel") > 0.5 || gml_Script_isRoom(_inst, _other, "rLevel2") > 0.5 || gml_Script_isRoom(_inst, _other, "rLevel3") > 0.5 || gml_Script_isRoom(_inst, _other, "rOlmec") > 0.5) {
        return 1;
    }
    return 0;
}

// #####################################################################################################
// //
// // isInShop(x, y)
// //
// // Is this point (x, y) in a shop?
// //
//
// tx = argument0;
// ty = argument1;
//
// if (global.roomPath[scrGetRoomX(tx), scrGetRoomY(ty)] == 4 or global.roomPath[scrGetRoomX(tx), scrGetRoomY(ty)] == 5)
//     return true;
//
// return false;
//
function gml_Script_isInShop(_inst, _other, argument0, argument1) {
    _inst.gmltx = argument0;
    _inst.gmlty = argument1;
    if (
        global.gmlroomPath[~~gml_Script_scrGetRoomX(_inst, _other, _inst.gmltx)][~~gml_Script_scrGetRoomY(_inst, _other, _inst.gmlty)] == 4 ||
        global.gmlroomPath[~~gml_Script_scrGetRoomX(_inst, _other, _inst.gmltx)][~~gml_Script_scrGetRoomY(_inst, _other, _inst.gmlty)] == 5
    ) {
        return 1;
    }
    return 0;
}

// #####################################################################################################
