function gml_Script_playMusic(_inst, _other, argument0, argument1) {
    if (global.gmlmusic > 0.5 && !(gml_Script_SS_IsSoundPlaying(_inst, _other, argument0) > 0.5)) {
        {
            if (argument1 > 0.5) {
                {
                    gml_Script_SS_LoopMusic(_inst, _other, argument0);
                }
            } else {
                {
                    gml_Script_SS_LoopMusic(_inst, _other, argument0);
                }
            }
        }
    } else {
        {
        }
    }
}

