//
function gml_Script_startMusic(_inst, _other) {
    if (global.gmlmusic > 0.5) {
        {
            if (instance_exists(441) > 0.5) {
                {
                    if (yyInst(441).gmlmusic == "LUSH") {
                        {
                            gml_Script_playMusic(_inst, _other, global.gmlmusLush, 1);
                            gml_Script_SS_SetSoundVol(_inst, _other, global.gmlmusLush, 2000 + 8000 * (global.gmlmusicVol / 18));
                        }
                    } else {
                        if (yyInst(441).gmlmusic == "ICE") {
                            {
                                gml_Script_playMusic(_inst, _other, global.gmlmusIce, 1);
                                gml_Script_SS_SetSoundVol(_inst, _other, global.gmlmusIce, 2000 + 8000 * (global.gmlmusicVol / 18));
                            }
                        } else {
                            if (yyInst(441).gmlmusic == "TEMPLE") {
                                {
                                    gml_Script_playMusic(_inst, _other, global.gmlmusTemple, 1);
                                    gml_Script_SS_SetSoundVol(_inst, _other, global.gmlmusTemple, 2000 + 8000 * (global.gmlmusicVol / 18));
                                }
                            } else {
                                if (yyInst(441).gmlmusic == "BOSS") {
                                    {
                                        if (yyInst(454).gmlactive > 0.5) {
                                            {
                                                gml_Script_playMusic(_inst, _other, global.gmlmusBoss, 1);
                                                gml_Script_SS_SetSoundVol(_inst, _other, global.gmlmusBoss, 2000 + 8000 * (global.gmlmusicVol / 18));
                                            }
                                        }
                                    }
                                } else {
                                    {
                                        gml_Script_playMusic(_inst, _other, global.gmlmusCave, 1);
                                        gml_Script_SS_SetSoundVol(_inst, _other, global.gmlmusCave, 2000 + 8000 * (global.gmlmusicVol / 18));
                                    }
                                }
                            }
                        }
                    }
                }
            } else {
                if (gml_Script_isLevel(_inst, _other) > 0.5) {
                    {
                        if (gml_Script_isRoom(_inst, _other, "rOlmec") > 0.5) {
                            {
                                if (yyInst(454).gmlactive > 0.5) {
                                    {
                                        gml_Script_playMusic(_inst, _other, global.gmlmusBoss, 1);
                                        gml_Script_SS_SetSoundVol(_inst, _other, global.gmlmusBoss, 2000 + 8000 * (global.gmlmusicVol / 18));
                                    }
                                }
                            }
                        } else {
                            if (global.gmllevelType == 1) {
                                {
                                    gml_Script_playMusic(_inst, _other, global.gmlmusLush, 1);
                                    gml_Script_SS_SetSoundVol(_inst, _other, global.gmlmusLush, 2000 + 8000 * (global.gmlmusicVol / 18));
                                }
                            } else {
                                if (global.gmllevelType == 2) {
                                    {
                                        gml_Script_playMusic(_inst, _other, global.gmlmusIce, 1);
                                        gml_Script_SS_SetSoundVol(_inst, _other, global.gmlmusIce, 2000 + 8000 * (global.gmlmusicVol / 18));
                                    }
                                } else {
                                    if (global.gmllevelType == 3) {
                                        {
                                            gml_Script_playMusic(_inst, _other, global.gmlmusTemple, 1);
                                            gml_Script_SS_SetSoundVol(_inst, _other, global.gmlmusTemple, 2000 + 8000 * (global.gmlmusicVol / 18));
                                        }
                                    } else {
                                        {
                                            gml_Script_playMusic(_inst, _other, global.gmlmusCave, 1);
                                            gml_Script_SS_SetSoundVol(_inst, _other, global.gmlmusCave, 2000 + 8000 * (global.gmlmusicVol / 18));
                                        }
                                    }
                                }
                            }
                        }
                    }
                } else {
                    if (gml_Script_isRoom(_inst, _other, "rTitle") > 0.5) {
                        gml_Script_SS_StopSound(_inst, _other, global.gmlmusTitle);
                    } else {
                        if (gml_Script_isRoom(_inst, _other, "rSun") > 0.5 || gml_Script_isRoom(_inst, _other, "rMoon") > 0.5 || gml_Script_isRoom(_inst, _other, "rStars") > 0.5) {
                            {
                                gml_Script_playMusic(_inst, _other, global.gmlmusBoss, 1);
                                gml_Script_SS_SetSoundVol(_inst, _other, global.gmlmusBoss, 2000 + 8000 * (global.gmlmusicVol / 18));
                            }
                        }
                    }
                }
            }
        }
    }
}

