function gml_Script_scrWriteStats(_inst, _other) {
    _inst.gmlfile = file_text_open_write(g_pBuiltIn.working_directory + "stats.txt");
    file_text_write_string(_inst.gmlfile, "+---------------------------+");
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "|  SPELUNKY EXTENDED STATS  |");
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "+---------------------------+");
    file_text_writeln(_inst.gmlfile);
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "CRATES OPENED:      ");
    file_text_write_string(_inst.gmlfile, string(global.gmltotalCrates));
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "CHESTS OPENED:      ");
    file_text_write_string(_inst.gmlfile, string(global.gmltotalChests));
    file_text_writeln(_inst.gmlfile);
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "IDOLS GRABBED:      ");
    file_text_write_string(_inst.gmlfile, string(global.gmlidolsGrabbed));
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "IDOLS CONVERTED:    ");
    file_text_write_string(_inst.gmlfile, string(global.gmlidolsConverted));
    file_text_writeln(_inst.gmlfile);
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "DAMSELS GRABBED:    ");
    file_text_write_string(_inst.gmlfile, string(global.gmldamselsGrabbed));
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "KISSES BOUGHT:      ");
    file_text_write_string(_inst.gmlfile, string(global.gmlkissesBought));
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "DAMSELS BOUGHT:     ");
    file_text_write_string(_inst.gmlfile, string(global.gmldamselsBought));
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "DAMSELS SAVED:      ");
    file_text_write_string(_inst.gmlfile, string(global.gmldamselsSavedTotal));
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "DAMSELS KILLED:     ");
    file_text_write_string(_inst.gmlfile, string(global.gmldamselsKilledTotal));
    file_text_writeln(_inst.gmlfile);
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "ITEMS BOUGHT:       ");
    file_text_write_string(_inst.gmlfile, string(global.gmlitemsBought));
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "ITEMS STOLEN:       ");
    file_text_write_string(_inst.gmlfile, string(global.gmlitemsStolen));
    file_text_writeln(_inst.gmlfile);
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "DICE GAMES PLAYED:  ");
    file_text_write_string(_inst.gmlfile, string(global.gmldiceGamesPlayed));
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "DICE GAMES WON:     ");
    file_text_write_string(_inst.gmlfile, string(global.gmldiceGamesWon));
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "DICE GAMES LOST:    ");
    file_text_write_string(_inst.gmlfile, string(global.gmldiceGamesLost));
    file_text_writeln(_inst.gmlfile);
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "LEVEL        DEATHS");
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "------------+------------");
    file_text_writeln(_inst.gmlfile);
    _inst.gmltotalDeaths = 0;
    for (_inst.gmli = 0; _inst.gmli < 16; _inst.gmli += 1) {
        {
            if (_inst.gmli + 1 < 10) {
                file_text_write_string(_inst.gmlfile, " " + string(_inst.gmli + 1) + "          | ");
            } else {
                file_text_write_string(_inst.gmlfile, " " + string(_inst.gmli + 1) + "         | ");
            }
            _inst.gmltotalDeaths += global.gmllevelDeaths[~~_inst.gmli];
            file_text_write_string(_inst.gmlfile, string(global.gmllevelDeaths[~~_inst.gmli]));
            file_text_writeln(_inst.gmlfile);
        }
    }
    file_text_write_string(_inst.gmlfile, "------------+------------");
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, " TOTAL      | ");
    file_text_write_string(_inst.gmlfile, string(_inst.gmltotalDeaths));
    file_text_writeln(_inst.gmlfile);
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "ENEMY        DEATHS");
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "------------+------------");
    file_text_writeln(_inst.gmlfile);
    for (_inst.gmli = 0; _inst.gmli < 24; _inst.gmli += 1) {
        {
            if (global.gmlenemyDeaths[~~_inst.gmli] == 0) {
                file_text_write_string(_inst.gmlfile, " ???        | ");
            } else {
                {
                    switch (_inst.gmli) {
                        case 0: {
                            file_text_write_string(_inst.gmlfile, " BAT        | ");
                            break;
                        }
                        case 1: {
                            file_text_write_string(_inst.gmlfile, " SNAKE      | ");
                            break;
                        }
                        case 2: {
                            file_text_write_string(_inst.gmlfile, " SPIDER     | ");
                            break;
                        }
                        case 3: {
                            file_text_write_string(_inst.gmlfile, " G. SPIDER  | ");
                            break;
                        }
                        case 4: {
                            file_text_write_string(_inst.gmlfile, " CAVEMAN    | ");
                            break;
                        }
                        case 5: {
                            file_text_write_string(_inst.gmlfile, " SKELETON   | ");
                            break;
                        }
                        case 6: {
                            file_text_write_string(_inst.gmlfile, " ZOMBIE     | ");
                            break;
                        }
                        case 7: {
                            file_text_write_string(_inst.gmlfile, " VAMPIRE    | ");
                            break;
                        }
                        case 8: {
                            file_text_write_string(_inst.gmlfile, " FROG       | ");
                            break;
                        }
                        case 9: {
                            file_text_write_string(_inst.gmlfile, " FIRE FROG  | ");
                            break;
                        }
                        case 10: {
                            file_text_write_string(_inst.gmlfile, " MANTRAP    | ");
                            break;
                        }
                        case 11: {
                            file_text_write_string(_inst.gmlfile, " PIRANHA    | ");
                            break;
                        }
                        case 12: {
                            file_text_write_string(_inst.gmlfile, " MEGAMOUTH  | ");
                            break;
                        }
                        case 13: {
                            file_text_write_string(_inst.gmlfile, " YETI       | ");
                            break;
                        }
                        case 14: {
                            file_text_write_string(_inst.gmlfile, " YETI KING  | ");
                            break;
                        }
                        case 15: {
                            file_text_write_string(_inst.gmlfile, " ALIEN      | ");
                            break;
                        }
                        case 16: {
                            file_text_write_string(_inst.gmlfile, " UFO        | ");
                            break;
                        }
                        case 17: {
                            file_text_write_string(_inst.gmlfile, " ALIEN BOSS | ");
                            break;
                        }
                        case 18: {
                            file_text_write_string(_inst.gmlfile, " HAWKMAN    | ");
                            break;
                        }
                        case 19: {
                            file_text_write_string(_inst.gmlfile, " SHOPKEEPER | ");
                            break;
                        }
                        case 20: {
                            file_text_write_string(_inst.gmlfile, " TOMB LORD  | ");
                            break;
                        }
                        case 21: {
                            file_text_write_string(_inst.gmlfile, " MAGMA MAN  | ");
                            break;
                        }
                        case 22: {
                            file_text_write_string(_inst.gmlfile, " OLMEC      | ");
                            break;
                        }
                        case 23: {
                            file_text_write_string(_inst.gmlfile, " GHOST      | ");
                            break;
                        }
                    }
                }
            }
            file_text_write_string(_inst.gmlfile, string(global.gmlenemyDeaths[~~_inst.gmli]));
            file_text_writeln(_inst.gmlfile);
        }
    }
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "MISC         DEATHS");
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "------------+------------");
    file_text_writeln(_inst.gmlfile);
    for (_inst.gmli = 0; _inst.gmli < 12; _inst.gmli += 1) {
        {
            if (global.gmlmiscDeaths[~~_inst.gmli] == 0) {
                file_text_write_string(_inst.gmlfile, " ???        | ");
            } else {
                {
                    switch (_inst.gmli) {
                        case 0: {
                            file_text_write_string(_inst.gmlfile, " ROCK       | ");
                            break;
                        }
                        case 1: {
                            file_text_write_string(_inst.gmlfile, " EXPLOSION  | ");
                            break;
                        }
                        case 2: {
                            file_text_write_string(_inst.gmlfile, " CRUSHED    | ");
                            break;
                        }
                        case 3: {
                            file_text_write_string(_inst.gmlfile, " LONG FALL  | ");
                            break;
                        }
                        case 4: {
                            file_text_write_string(_inst.gmlfile, " SPIKES     | ");
                            break;
                        }
                        case 5: {
                            file_text_write_string(_inst.gmlfile, " BOULDER    | ");
                            break;
                        }
                        case 6: {
                            file_text_write_string(_inst.gmlfile, " ARROW TRAP | ");
                            break;
                        }
                        case 7: {
                            file_text_write_string(_inst.gmlfile, " SPEAR TRAP | ");
                            break;
                        }
                        case 8: {
                            file_text_write_string(_inst.gmlfile, " SMASH TRAP | ");
                            break;
                        }
                        case 9: {
                            file_text_write_string(_inst.gmlfile, " CEILING T. | ");
                            break;
                        }
                        case 10: {
                            file_text_write_string(_inst.gmlfile, " PIT        | ");
                            break;
                        }
                        case 11: {
                            file_text_write_string(_inst.gmlfile, " LAVA       | ");
                            break;
                        }
                    }
                }
            }
            file_text_write_string(_inst.gmlfile, string(global.gmlmiscDeaths[~~_inst.gmli]));
            file_text_writeln(_inst.gmlfile);
        }
    }
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "ENEMY        KILLS");
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, "------------+------------");
    file_text_writeln(_inst.gmlfile);
    _inst.gmltotalKills = 0;
    for (_inst.gmli = 0; _inst.gmli < 22; _inst.gmli += 1) {
        {
            if (global.gmlenemyKills[~~_inst.gmli] == 0) {
                file_text_write_string(_inst.gmlfile, " ???        | ");
            } else {
                {
                    switch (_inst.gmli) {
                        case 0: {
                            file_text_write_string(_inst.gmlfile, " BAT        | ");
                            break;
                        }
                        case 1: {
                            file_text_write_string(_inst.gmlfile, " SNAKE      | ");
                            break;
                        }
                        case 2: {
                            file_text_write_string(_inst.gmlfile, " SPIDER     | ");
                            break;
                        }
                        case 3: {
                            file_text_write_string(_inst.gmlfile, " G. SPIDER  | ");
                            break;
                        }
                        case 4: {
                            file_text_write_string(_inst.gmlfile, " CAVEMAN    | ");
                            break;
                        }
                        case 5: {
                            file_text_write_string(_inst.gmlfile, " SKELETON   | ");
                            break;
                        }
                        case 6: {
                            file_text_write_string(_inst.gmlfile, " ZOMBIE     | ");
                            break;
                        }
                        case 7: {
                            file_text_write_string(_inst.gmlfile, " VAMPIRE    | ");
                            break;
                        }
                        case 8: {
                            file_text_write_string(_inst.gmlfile, " FROG       | ");
                            break;
                        }
                        case 9: {
                            file_text_write_string(_inst.gmlfile, " FIRE FROG  | ");
                            break;
                        }
                        case 10: {
                            file_text_write_string(_inst.gmlfile, " MANTRAP    | ");
                            break;
                        }
                        case 11: {
                            file_text_write_string(_inst.gmlfile, " PIRANHA    | ");
                            break;
                        }
                        case 12: {
                            file_text_write_string(_inst.gmlfile, " MEGAMOUTH  | ");
                            break;
                        }
                        case 13: {
                            file_text_write_string(_inst.gmlfile, " YETI       | ");
                            break;
                        }
                        case 14: {
                            file_text_write_string(_inst.gmlfile, " YETI KING  | ");
                            break;
                        }
                        case 15: {
                            file_text_write_string(_inst.gmlfile, " ALIEN      | ");
                            break;
                        }
                        case 16: {
                            file_text_write_string(_inst.gmlfile, " UFO        | ");
                            break;
                        }
                        case 17: {
                            file_text_write_string(_inst.gmlfile, " ALIEN BOSS | ");
                            break;
                        }
                        case 18: {
                            file_text_write_string(_inst.gmlfile, " HAWKMAN    | ");
                            break;
                        }
                        case 19: {
                            file_text_write_string(_inst.gmlfile, " SHOPKEEPER | ");
                            break;
                        }
                        case 20: {
                            file_text_write_string(_inst.gmlfile, " TOMB LORD  | ");
                            break;
                        }
                        case 21: {
                            file_text_write_string(_inst.gmlfile, " OLMEC      | ");
                            break;
                        }
                    }
                }
            }
            _inst.gmltotalKills += global.gmlenemyKills[~~_inst.gmli];
            file_text_write_string(_inst.gmlfile, string(global.gmlenemyKills[~~_inst.gmli]));
            file_text_writeln(_inst.gmlfile);
            if (_inst.gmli == 8) {
                {
                    if (global.gmltotalMonkeyKills == 0) {
                        file_text_write_string(_inst.gmlfile, " ???        | ");
                    } else {
                        {
                            file_text_write_string(_inst.gmlfile, " MONKEY     | ");
                        }
                    }
                    _inst.gmltotalKills += global.gmltotalMonkeyKills;
                    file_text_write_string(_inst.gmlfile, string(global.gmltotalMonkeyKills));
                    file_text_writeln(_inst.gmlfile);
                }
            }
        }
    }
    file_text_write_string(_inst.gmlfile, "------------+------------");
    file_text_writeln(_inst.gmlfile);
    file_text_write_string(_inst.gmlfile, " TOTAL      | ");
    file_text_write_string(_inst.gmlfile, string(_inst.gmltotalKills));
    file_text_writeln(_inst.gmlfile);
    file_text_close(_inst.gmlfile);
}

