function gml_Script_scrReadStats(_inst, _other) {
    global.gmlgameStart = 0 ? 1 : 0;
    global.gmltotalCrates = 0;
    global.gmltotalChests = 0;
    global.gmlidolsGrabbed = 0;
    global.gmlidolsConverted = 0;
    global.gmldamselsGrabbed = 0;
    global.gmlkissesBought = 0;
    global.gmldamselsBought = 0;
    global.gmldamselsSavedTotal = 0;
    global.gmldamselsKilledTotal = 0;
    global.gmlitemsBought = 0;
    global.gmlitemsStolen = 0;
    global.gmldiceGamesPlayed = 0;
    global.gmldiceGamesWon = 0;
    global.gmldiceGamesLost = 0;
    for (_inst.gmli = 0; _inst.gmli < 16; _inst.gmli += 1) {
        {
            if (!(global.gmllevelDeaths instanceof Array)) {
                global.gmllevelDeaths = [];
                global.gmllevelDeaths.__yy_owner = 1142766156;
            } else if (global.gmllevelDeaths.__yy_owner !== 1142766156) {
                global.gmllevelDeaths = global.gmllevelDeaths.slice(0);
                global.gmllevelDeaths.__yy_owner = 1142766156;
            }
            global.gmllevelDeaths[~~_inst.gmli] = 0;
        }
    }
    for (_inst.gmli = 0; _inst.gmli < 24; _inst.gmli += 1) {
        {
            if (!(global.gmlenemyDeaths instanceof Array)) {
                global.gmlenemyDeaths = [];
                global.gmlenemyDeaths.__yy_owner = 2367926208;
            } else if (global.gmlenemyDeaths.__yy_owner !== 2367926208) {
                global.gmlenemyDeaths = global.gmlenemyDeaths.slice(0);
                global.gmlenemyDeaths.__yy_owner = 2367926208;
            }
            global.gmlenemyDeaths[~~_inst.gmli] = 0;
        }
    }
    for (_inst.gmli = 0; _inst.gmli < 12; _inst.gmli += 1) {
        {
            if (!(global.gmlmiscDeaths instanceof Array)) {
                global.gmlmiscDeaths = [];
                global.gmlmiscDeaths.__yy_owner = 1510388366;
            } else if (global.gmlmiscDeaths.__yy_owner !== 1510388366) {
                global.gmlmiscDeaths = global.gmlmiscDeaths.slice(0);
                global.gmlmiscDeaths.__yy_owner = 1510388366;
            }
            global.gmlmiscDeaths[~~_inst.gmli] = 0;
        }
    }
    for (_inst.gmli = 0; _inst.gmli < 22; _inst.gmli += 1) {
        {
            if (!(global.gmlenemyKills instanceof Array)) {
                global.gmlenemyKills = [];
                global.gmlenemyKills.__yy_owner = 818832447;
            } else if (global.gmlenemyKills.__yy_owner !== 818832447) {
                global.gmlenemyKills = global.gmlenemyKills.slice(0);
                global.gmlenemyKills.__yy_owner = 818832447;
            }
            global.gmlenemyKills[~~_inst.gmli] = 0;
        }
    }
    global.gmltotalMonkeyKills = 0;
    _inst.gmlfilePath = g_pBuiltIn.working_directory + "stats.txt";
    if (file_exists(_inst.gmlfilePath) > 0.5) {
        {
            _inst.gmlfile = file_text_open_read(_inst.gmlfilePath);
            file_text_readln(_inst.gmlfile);
            file_text_readln(_inst.gmlfile);
            file_text_readln(_inst.gmlfile);
            file_text_readln(_inst.gmlfile);
            _inst.gmlstr = file_text_read_string(_inst.gmlfile);
            _inst.gmlstr = string_delete(_inst.gmlstr, 1, 20);
            global.gmltotalCrates = real(_inst.gmlstr);
            file_text_readln(_inst.gmlfile);
            _inst.gmlstr = file_text_read_string(_inst.gmlfile);
            _inst.gmlstr = string_delete(_inst.gmlstr, 1, 20);
            global.gmltotalChests = real(_inst.gmlstr);
            file_text_readln(_inst.gmlfile);
            file_text_readln(_inst.gmlfile);
            _inst.gmlstr = file_text_read_string(_inst.gmlfile);
            _inst.gmlstr = string_delete(_inst.gmlstr, 1, 20);
            global.gmlidolsGrabbed = real(_inst.gmlstr);
            file_text_readln(_inst.gmlfile);
            _inst.gmlstr = file_text_read_string(_inst.gmlfile);
            _inst.gmlstr = string_delete(_inst.gmlstr, 1, 20);
            global.gmlidolsConverted = real(_inst.gmlstr);
            file_text_readln(_inst.gmlfile);
            file_text_readln(_inst.gmlfile);
            _inst.gmlstr = file_text_read_string(_inst.gmlfile);
            _inst.gmlstr = string_delete(_inst.gmlstr, 1, 20);
            global.gmldamselsGrabbed = real(_inst.gmlstr);
            file_text_readln(_inst.gmlfile);
            _inst.gmlstr = file_text_read_string(_inst.gmlfile);
            _inst.gmlstr = string_delete(_inst.gmlstr, 1, 20);
            global.gmlkissesBought = real(_inst.gmlstr);
            file_text_readln(_inst.gmlfile);
            _inst.gmlstr = file_text_read_string(_inst.gmlfile);
            _inst.gmlstr = string_delete(_inst.gmlstr, 1, 20);
            global.gmldamselsBought = real(_inst.gmlstr);
            file_text_readln(_inst.gmlfile);
            _inst.gmlstr = file_text_read_string(_inst.gmlfile);
            _inst.gmlstr = string_delete(_inst.gmlstr, 1, 20);
            global.gmldamselsSavedTotal = real(_inst.gmlstr);
            file_text_readln(_inst.gmlfile);
            _inst.gmlstr = file_text_read_string(_inst.gmlfile);
            _inst.gmlstr = string_delete(_inst.gmlstr, 1, 20);
            global.gmldamselsKilledTotal = real(_inst.gmlstr);
            file_text_readln(_inst.gmlfile);
            file_text_readln(_inst.gmlfile);
            _inst.gmlstr = file_text_read_string(_inst.gmlfile);
            _inst.gmlstr = string_delete(_inst.gmlstr, 1, 20);
            global.gmlitemsBought = real(_inst.gmlstr);
            file_text_readln(_inst.gmlfile);
            _inst.gmlstr = file_text_read_string(_inst.gmlfile);
            _inst.gmlstr = string_delete(_inst.gmlstr, 1, 20);
            global.gmlitemsStolen = real(_inst.gmlstr);
            file_text_readln(_inst.gmlfile);
            file_text_readln(_inst.gmlfile);
            _inst.gmlstr = file_text_read_string(_inst.gmlfile);
            _inst.gmlstr = string_delete(_inst.gmlstr, 1, 20);
            global.gmldiceGamesPlayed = real(_inst.gmlstr);
            file_text_readln(_inst.gmlfile);
            _inst.gmlstr = file_text_read_string(_inst.gmlfile);
            _inst.gmlstr = string_delete(_inst.gmlstr, 1, 20);
            global.gmldiceGamesWon = real(_inst.gmlstr);
            file_text_readln(_inst.gmlfile);
            _inst.gmlstr = file_text_read_string(_inst.gmlfile);
            _inst.gmlstr = string_delete(_inst.gmlstr, 1, 20);
            global.gmldiceGamesLost = real(_inst.gmlstr);
            file_text_readln(_inst.gmlfile);
            file_text_readln(_inst.gmlfile);
            file_text_readln(_inst.gmlfile);
            _inst.gmlstr = file_text_read_string(_inst.gmlfile);
            for (_inst.gmli = 0; _inst.gmli < 16; _inst.gmli += 1) {
                {
                    file_text_readln(_inst.gmlfile);
                    _inst.gmlstr = file_text_read_string(_inst.gmlfile);
                    _inst.gmlstr = string_delete(_inst.gmlstr, 1, 14);
                    if (!(global.gmllevelDeaths instanceof Array)) {
                        global.gmllevelDeaths = [];
                        global.gmllevelDeaths.__yy_owner = 1142766156;
                    } else if (global.gmllevelDeaths.__yy_owner !== 1142766156) {
                        global.gmllevelDeaths = global.gmllevelDeaths.slice(0);
                        global.gmllevelDeaths.__yy_owner = 1142766156;
                    }
                    global.gmllevelDeaths[~~_inst.gmli] = real(_inst.gmlstr);
                }
            }
            file_text_readln(_inst.gmlfile);
            file_text_readln(_inst.gmlfile);
            file_text_readln(_inst.gmlfile);
            file_text_readln(_inst.gmlfile);
            file_text_readln(_inst.gmlfile);
            for (_inst.gmli = 0; _inst.gmli < 24; _inst.gmli += 1) {
                {
                    file_text_readln(_inst.gmlfile);
                    _inst.gmlstr = file_text_read_string(_inst.gmlfile);
                    _inst.gmlstr = string_delete(_inst.gmlstr, 1, 14);
                    if (!(global.gmlenemyDeaths instanceof Array)) {
                        global.gmlenemyDeaths = [];
                        global.gmlenemyDeaths.__yy_owner = 2367926208;
                    } else if (global.gmlenemyDeaths.__yy_owner !== 2367926208) {
                        global.gmlenemyDeaths = global.gmlenemyDeaths.slice(0);
                        global.gmlenemyDeaths.__yy_owner = 2367926208;
                    }
                    global.gmlenemyDeaths[~~_inst.gmli] = real(_inst.gmlstr);
                }
            }
            file_text_readln(_inst.gmlfile);
            file_text_readln(_inst.gmlfile);
            file_text_readln(_inst.gmlfile);
            for (_inst.gmli = 0; _inst.gmli < 12; _inst.gmli += 1) {
                {
                    file_text_readln(_inst.gmlfile);
                    _inst.gmlstr = file_text_read_string(_inst.gmlfile);
                    _inst.gmlstr = string_delete(_inst.gmlstr, 1, 14);
                    if (!(global.gmlmiscDeaths instanceof Array)) {
                        global.gmlmiscDeaths = [];
                        global.gmlmiscDeaths.__yy_owner = 1510388366;
                    } else if (global.gmlmiscDeaths.__yy_owner !== 1510388366) {
                        global.gmlmiscDeaths = global.gmlmiscDeaths.slice(0);
                        global.gmlmiscDeaths.__yy_owner = 1510388366;
                    }
                    global.gmlmiscDeaths[~~_inst.gmli] = real(_inst.gmlstr);
                }
            }
            file_text_readln(_inst.gmlfile);
            file_text_readln(_inst.gmlfile);
            file_text_readln(_inst.gmlfile);
            for (_inst.gmli = 0; _inst.gmli < 22; _inst.gmli += 1) {
                {
                    file_text_readln(_inst.gmlfile);
                    _inst.gmlstr = file_text_read_string(_inst.gmlfile);
                    _inst.gmlstr = string_delete(_inst.gmlstr, 1, 14);
                    if (!(global.gmlenemyKills instanceof Array)) {
                        global.gmlenemyKills = [];
                        global.gmlenemyKills.__yy_owner = 818832447;
                    } else if (global.gmlenemyKills.__yy_owner !== 818832447) {
                        global.gmlenemyKills = global.gmlenemyKills.slice(0);
                        global.gmlenemyKills.__yy_owner = 818832447;
                    }
                    global.gmlenemyKills[~~_inst.gmli] = real(_inst.gmlstr);
                    if (_inst.gmli == 8) {
                        {
                            file_text_readln(_inst.gmlfile);
                            _inst.gmlstr = file_text_read_string(_inst.gmlfile);
                            _inst.gmlstr = string_delete(_inst.gmlstr, 1, 14);
                            global.gmltotalMonkeyKills = real(_inst.gmlstr);
                        }
                    }
                }
            }
            file_text_readln(_inst.gmlfile);
            file_text_close(_inst.gmlfile);
        }
    }
}

