// end else begin
//   return external_call(global.dll_SS_SetSoundPan,argument0,string(argument1));
// end;
//
function gml_Script_SS_SetSoundPan(_inst, _other, argument0, argument1) {
    return 0;
    if (is_real(argument0) > 0.5) {
        return "0";
    }
    if (is_string(argument1) > 0.5) {
        {
            return external_call(global.gmldll_SS_SetSoundPan, argument0, argument1);
        }
    } else {
        {
            return external_call(global.gmldll_SS_SetSoundPan, argument0, string(argument1));
        }
    }
}

