// ///getPlatform
//
// global.html5Build = !(os_browser == browser_not_a_browser);
// global.mobileBuild = (os_type == os_android) or (os_type == os_ios);
//
// if (global.html5Build) {
//     global.electronBuild = isElectron();
// } else {
//     global.electronBuild = false;
// }
//
// global.browserBuild = ((global.html5Build) and (!global.electronBuild));
//
function gml_Script_getPlatform(_inst, _other) {
    global.gmlhtml5Build = !(g_pBuiltIn.get_os_browser() == -1) ? 1 : 0;
    global.gmlmobileBuild = g_pBuiltIn.get_os_type() == 4 || g_pBuiltIn.get_os_type() == 3 ? 1 : 0;
    if (global.gmlhtml5Build > 0.5) {
        {
            global.gmlelectronBuild = isElectron();
        }
    } else {
        {
            global.gmlelectronBuild = 0 ? 1 : 0;
        }
    }
    global.gmlbrowserBuild = global.gmlhtml5Build > 0.5 && !(global.gmlelectronBuild > 0.5) ? 1 : 0;
}

