function gml_Script_enableTouchInput(_inst, _other) {
    _inst.gmlscale_level = global.gmldisplay_h / 240;
    _inst.gmlvkey_size = 32 * _inst.gmlscale_level;
    virtual_key_add(global.gmltouchCorrectionH, global.gmldisplay_h - 2 * _inst.gmlvkey_size - global.gmltouchCorrectionV, _inst.gmlvkey_size, _inst.gmlvkey_size, global.gmlkeyLeftVal);
    virtual_key_add(global.gmltouchCorrectionH, global.gmldisplay_h - 3 * _inst.gmlvkey_size - global.gmltouchCorrectionV / 3, _inst.gmlvkey_size, _inst.gmlvkey_size, global.gmlkeyLeftVal);
    virtual_key_add(global.gmltouchCorrectionH, global.gmldisplay_h - 3 * _inst.gmlvkey_size - global.gmltouchCorrectionV / 3, _inst.gmlvkey_size, _inst.gmlvkey_size, global.gmlkeyUpVal);
    virtual_key_add(_inst.gmlvkey_size + global.gmltouchCorrectionH, global.gmldisplay_h - 3 * _inst.gmlvkey_size - global.gmltouchCorrectionV / 3, _inst.gmlvkey_size, _inst.gmlvkey_size, global.gmlkeyUpVal);
    virtual_key_add(2 * _inst.gmlvkey_size + global.gmltouchCorrectionH, global.gmldisplay_h - 3 * _inst.gmlvkey_size - global.gmltouchCorrectionV / 3, _inst.gmlvkey_size, _inst.gmlvkey_size, global.gmlkeyRightVal);
    virtual_key_add(2 * _inst.gmlvkey_size + global.gmltouchCorrectionH, global.gmldisplay_h - 3 * _inst.gmlvkey_size - global.gmltouchCorrectionV / 3, _inst.gmlvkey_size, _inst.gmlvkey_size, global.gmlkeyUpVal);
    virtual_key_add(2 * _inst.gmlvkey_size + global.gmltouchCorrectionH, global.gmldisplay_h - 2 * _inst.gmlvkey_size - global.gmltouchCorrectionV, _inst.gmlvkey_size, _inst.gmlvkey_size, global.gmlkeyRightVal);
    virtual_key_add(2 * _inst.gmlvkey_size + global.gmltouchCorrectionH, global.gmldisplay_h - _inst.gmlvkey_size - global.gmltouchCorrectionV, _inst.gmlvkey_size, _inst.gmlvkey_size, global.gmlkeyRightVal);
    virtual_key_add(2 * _inst.gmlvkey_size + global.gmltouchCorrectionH, global.gmldisplay_h - _inst.gmlvkey_size - global.gmltouchCorrectionV, _inst.gmlvkey_size, _inst.gmlvkey_size, global.gmlkeyDownVal);
    virtual_key_add(_inst.gmlvkey_size + global.gmltouchCorrectionH, global.gmldisplay_h - _inst.gmlvkey_size - global.gmltouchCorrectionV, _inst.gmlvkey_size, _inst.gmlvkey_size, global.gmlkeyDownVal);
    virtual_key_add(global.gmltouchCorrectionH, global.gmldisplay_h - _inst.gmlvkey_size - global.gmltouchCorrectionV, _inst.gmlvkey_size, _inst.gmlvkey_size, global.gmlkeyLeftVal);
    virtual_key_add(global.gmltouchCorrectionH, global.gmldisplay_h - _inst.gmlvkey_size - global.gmltouchCorrectionV, _inst.gmlvkey_size, _inst.gmlvkey_size, global.gmlkeyDownVal);
    virtual_key_add(global.gmldisplay_w - global.gmltouchCorrectionH - 2.5 * _inst.gmlvkey_size, global.gmldisplay_h - global.gmltouchCorrectionV - _inst.gmlvkey_size, _inst.gmlvkey_size, _inst.gmlvkey_size, global.gmlkeyAttackVal);
    virtual_key_add(global.gmldisplay_w - global.gmltouchCorrectionH - _inst.gmlvkey_size, global.gmldisplay_h - global.gmltouchCorrectionV - _inst.gmlvkey_size, _inst.gmlvkey_size, _inst.gmlvkey_size, 74);
    virtual_key_add(global.gmldisplay_w - global.gmltouchCorrectionH - 2.5 * _inst.gmlvkey_size, global.gmldisplay_h - global.gmltouchCorrectionV / 2 - 2.5 * _inst.gmlvkey_size, _inst.gmlvkey_size, _inst.gmlvkey_size, global.gmlkeyItemVal);
    virtual_key_add(global.gmldisplay_w - global.gmltouchCorrectionH - _inst.gmlvkey_size, global.gmldisplay_h - global.gmltouchCorrectionV / 2 - 2.5 * _inst.gmlvkey_size, _inst.gmlvkey_size, _inst.gmlvkey_size, global.gmlkeyRunVal);
    virtual_key_add(global.gmldisplay_w - global.gmltouchCorrectionH - _inst.gmlvkey_size, 0 + global.gmltouchCorrectionV, _inst.gmlvkey_size, _inst.gmlvkey_size, 27);
    virtual_key_add(global.gmldisplay_w - global.gmltouchCorrectionH - _inst.gmlvkey_size, 0 + global.gmltouchCorrectionV, _inst.gmlvkey_size, _inst.gmlvkey_size, global.gmlkeyStartVal);
    virtual_key_add(global.gmldisplay_w - global.gmltouchCorrectionH - _inst.gmlvkey_size, _inst.gmlvkey_size + global.gmltouchCorrectionV / 2, _inst.gmlvkey_size, _inst.gmlvkey_size, global.gmlkeyPayVal);
    virtual_key_add(global.gmldisplay_w - global.gmltouchCorrectionH - _inst.gmlvkey_size, 2 * _inst.gmlvkey_size + global.gmltouchCorrectionV / 3, _inst.gmlvkey_size, _inst.gmlvkey_size, global.gmlkeyRopeVal);
    virtual_key_add(global.gmldisplay_w - global.gmltouchCorrectionH - _inst.gmlvkey_size, 3 * _inst.gmlvkey_size + global.gmltouchCorrectionV / 4, _inst.gmlvkey_size, _inst.gmlvkey_size, global.gmlkeyBombVal);
    if (global.gmldebugBuild > 0.5) {
        {
            virtual_key_add(global.gmltouchCorrectionH, _inst.gmlvkey_size - global.gmltouchCorrectionV, _inst.gmlvkey_size, _inst.gmlvkey_size, 113);
            virtual_key_add(global.gmltouchCorrectionH, 2 * _inst.gmlvkey_size - global.gmltouchCorrectionV, _inst.gmlvkey_size, _inst.gmlvkey_size, 114);
            virtual_key_add(global.gmltouchCorrectionH, 3 * _inst.gmlvkey_size - global.gmltouchCorrectionV, _inst.gmlvkey_size, _inst.gmlvkey_size, 115);
            virtual_key_add(_inst.gmlvkey_size + global.gmltouchCorrectionH, 3 * _inst.gmlvkey_size - global.gmltouchCorrectionV, _inst.gmlvkey_size, _inst.gmlvkey_size, 116);
        }
    }
}

