//     Spelunky is distributed in the hope that it will be entertaining and useful,
//     but WITHOUT WARRANTY.  Please see the Spelunky User License for more details.
//
//     The Spelunky User License should be available in "Game Information", which
//     can be found in the Resource Explorer, or as an external file called COPYING.
//     If not, please obtain a new copy of Spelunky from <http://spelunkyworld.com/>
//
// ***********************************************************************************/
//
// setCollisionBounds(2, 6, 14, 16);
//
// if (colLeft and not colRight)
// {
//     x += 1;
// }
// else if (colRight)
// {
//     x -= 1;
// }
//
// if (colLeft or colRight)
// {
//     xVel = -xVel * 0.5;
// }
//
// if (colTop and not colBot)
// {
//     y += 1;
// }
// else if (colBot)
// {
//     // bounce
//     if (yVel > 1) yVel = -yVel * 0.5;
//     else if (abs(yVel) < 1) yVel = 0;
//
//     // friction
//     if (abs(xVel) < 0.1) xVel = 0;
//     else if (abs(xVel) != 0) xVel *= 0.3;
// }
//
function gml_Script_scrCheckCollisions(_inst, _other) {
    gml_Script_setCollisionBounds(_inst, _other, 2, 6, 14, 16);
    if (_inst.gmlcolLeft > 0.5 && !(_inst.gmlcolRight > 0.5)) {
        {
            _inst.setx(_inst.x + 1);
        }
    } else {
        if (_inst.gmlcolRight > 0.5) {
            {
                _inst.setx(_inst.x - 1);
            }
        }
    }
    if (_inst.gmlcolLeft > 0.5 || _inst.gmlcolRight > 0.5) {
        {
            _inst.gmlxVel = -_inst.gmlxVel * 0.5;
        }
    }
    if (_inst.gmlcolTop > 0.5 && !(_inst.gmlcolBot > 0.5)) {
        {
            _inst.sety(_inst.y + 1);
        }
    } else {
        if (_inst.gmlcolBot > 0.5) {
            {
                if (_inst.gmlyVel > 1) {
                    _inst.gmlyVel = -_inst.gmlyVel * 0.5;
                } else {
                    if (abs(_inst.gmlyVel) < 1) {
                        _inst.gmlyVel = 0;
                    }
                }
                if (abs(_inst.gmlxVel) < 0.1) {
                    _inst.gmlxVel = 0;
                } else {
                    if (abs(_inst.gmlxVel) != 0) {
                        _inst.gmlxVel *= 0.3;
                    }
                }
            }
        }
    }
}

