// else if (global.favor > 0) global.message2 = tr("SHE SEEMS PLEASED WITH YOU.");
//
function gml_Script_scrGetFavorMsg(_inst, _other) {
    if (global.gmlfavor <= -8) {
        global.gmlmessage2 = gml_Script_tr(_inst, _other, "SHE SEEMS VERY ANGRY WITH YOU!");
    } else {
        if (global.gmlfavor < 0) {
            global.gmlmessage2 = gml_Script_tr(_inst, _other, "SHE SEEMS ANGRY WITH YOU.");
        } else {
            if (global.gmlfavor == 0) {
                global.gmlmessage2 = gml_Script_tr(_inst, _other, "SHE HAS FORGIVEN YOU!");
            } else {
                if (global.gmlfavor >= 32) {
                    {
                        if (global.gmlkaliGift >= 3 && global.gmlfavor >= 32 + (global.gmlkaliGift - 2) * 16) {
                            {
                                global.gmlmessage2 = gml_Script_tr(_inst, _other, "YOU FEEL INVIGORATED!");
                                global.gmlkaliGift += 1;
                                global.gmlplife += gml_Script_rand(_inst, _other, 4, 8);
                            }
                        } else {
                            if (global.gmlkaliGift >= 3) {
                                {
                                    global.gmlmessage2 = gml_Script_tr(_inst, _other, "SHE SEEMS ECSTATIC WITH YOU!");
                                }
                            } else {
                                if (global.gmlbombs < 80) {
                                    {
                                        global.gmlmessage2 = gml_Script_tr(_inst, _other, "YOUR SATCHEL FEELS VERY FULL NOW!");
                                        global.gmlkaliGift = 3;
                                        global.gmlbombs = 99;
                                    }
                                } else {
                                    {
                                        global.gmlmessage2 = gml_Script_tr(_inst, _other, "YOU FEEL INVIGORATED!");
                                        global.gmlkaliGift += 1;
                                        global.gmlplife += gml_Script_rand(_inst, _other, 4, 8);
                                    }
                                }
                            }
                        }
                    }
                } else {
                    if (global.gmlfavor >= 16) {
                        {
                            if (global.gmlkaliGift >= 2) {
                                {
                                    global.gmlmessage2 = gml_Script_tr(_inst, _other, "SHE SEEMS VERY HAPPY WITH YOU!");
                                }
                            } else {
                                {
                                    global.gmlmessage2 = gml_Script_tr(_inst, _other, "SHE BESTOWS A GIFT UPON YOU!");
                                    global.gmlkaliGift = 2;
                                    _inst.gmlobj = instance_create(yyInst(134).x, _inst.y - 8, 175);
                                    yyInst(_inst.gmlobj).gmlcost = 0;
                                    yyInst(_inst.gmlobj).gmlforSale = 0 ? 1 : 0;
                                }
                            }
                        }
                    } else {
                        if (global.gmlfavor >= 8) {
                            {
                                if (global.gmlkaliGift >= 1) {
                                    {
                                        global.gmlmessage2 = gml_Script_tr(_inst, _other, "SHE SEEMS HAPPY WITH YOU.");
                                    }
                                } else {
                                    {
                                        global.gmlmessage2 = gml_Script_tr(_inst, _other, "SHE BESTOWS A GIFT UPON YOU!");
                                        global.gmlkaliGift = 1;
                                        if (instance_exists(134) > 0.5) {
                                            {
                                                _inst.gmlobj = instance_create(yyInst(134).x, _inst.y - 8, 210);
                                                yyInst(_inst.gmlobj).gmlxVel = -1;
                                                yyInst(_inst.gmlobj).gmlyVel = 0;
                                                _inst.gmlobj = instance_create(yyInst(134).x, _inst.y - 8, 210);
                                                yyInst(_inst.gmlobj).gmlxVel = 1;
                                                yyInst(_inst.gmlobj).gmlyVel = 0;
                                                _inst.gmln = gml_Script_rand(_inst, _other, 1, 8);
                                                _inst.gmlm = _inst.gmln;
                                                while (1) {
                                                    {
                                                        if (_inst.gmln == 1 && !(global.gmlhasCape > 0.5) && !(global.gmlhasJetpack > 0.5)) {
                                                            {
                                                                _inst.gmlobj = instance_create(yyInst(134).x, _inst.y - 8, 180);
                                                                break;
                                                            }
                                                        } else {
                                                            if (_inst.gmln == 2 && !(global.gmlhasGloves > 0.5)) {
                                                                {
                                                                    _inst.gmlobj = instance_create(yyInst(134).x, _inst.y - 8, 177);
                                                                    break;
                                                                }
                                                            } else {
                                                                if (_inst.gmln == 3 && !(global.gmlhasSpectacles > 0.5)) {
                                                                    {
                                                                        _inst.gmlobj = instance_create(yyInst(134).x, _inst.y - 8, 172);
                                                                        break;
                                                                    }
                                                                } else {
                                                                    if (_inst.gmln == 4 && !(global.gmlhasMitt > 0.5)) {
                                                                        {
                                                                            _inst.gmlobj = instance_create(yyInst(134).x, _inst.y - 8, 178);
                                                                            break;
                                                                        }
                                                                    } else {
                                                                        if (_inst.gmln == 5 && !(global.gmlhasSpringShoes > 0.5)) {
                                                                            {
                                                                                _inst.gmlobj = instance_create(yyInst(134).x, _inst.y - 8, 169);
                                                                                break;
                                                                            }
                                                                        } else {
                                                                            if (_inst.gmln == 6 && !(global.gmlhasSpikeShoes > 0.5)) {
                                                                                {
                                                                                    _inst.gmlobj = instance_create(yyInst(134).x, _inst.y - 8, 170);
                                                                                    break;
                                                                                }
                                                                            } else {
                                                                                if (_inst.gmln == 7 && !(global.gmlhasStickyBombs > 0.5)) {
                                                                                    {
                                                                                        _inst.gmlobj = instance_create(yyInst(134).x, _inst.y - 8, 165);
                                                                                        break;
                                                                                    }
                                                                                } else {
                                                                                    if (_inst.gmln == 8 && !(global.gmlhasCompass > 0.5)) {
                                                                                        {
                                                                                            _inst.gmlobj = instance_create(yyInst(134).x, _inst.y - 8, 168);
                                                                                            break;
                                                                                        }
                                                                                    }
                                                                                }
                                                                            }
                                                                        }
                                                                    }
                                                                }
                                                            }
                                                        }
                                                        _inst.gmln += 1;
                                                        if (_inst.gmln > 8) {
                                                            _inst.gmln = 1;
                                                        }
                                                        if (_inst.gmln == _inst.gmlm) {
                                                            {
                                                                if (!(global.gmlhasJetpack > 0.5)) {
                                                                    _inst.gmlobj = instance_create(yyInst(134).x, _inst.y - 8, 179);
                                                                } else {
                                                                    _inst.gmlobj = instance_create(yyInst(134).x, _inst.y - 8, 164);
                                                                }
                                                                break;
                                                            }
                                                        }
                                                    }
                                                }
                                                yyInst(_inst.gmlobj).gmlcost = 0;
                                                yyInst(_inst.gmlobj).gmlforSale = 0 ? 1 : 0;
                                            }
                                        }
                                    }
                                }
                            }
                        } else {
                            if (global.gmlfavor > 0) {
                                global.gmlmessage2 = gml_Script_tr(_inst, _other, "SHE SEEMS PLEASED WITH YOU.");
                            }
                        }
                    }
                }
            }
        }
    }
}

