//             case gp_padd: return  "DOWN";
//             default: return string(argument[0]);
//         }
//         /*
//         if ((string_pos('X-Box', gamepadDesc) != 0) or
//                 (string_pos('Xbox', gamepadDesc) != 0) or
//                 (string_pos('X360', gamepadDesc) != 0))
//                 or global.mobileBuild {
//             switch (argument[0]) {
