//         return string(html5_gamepad_get_button_name(global.joyid, argument[0]));
//     }
// }
//
function gml_Script_scrGetJoy(_inst, _other) {
    if (file_exists(g_pBuiltIn.working_directory + "gamepadmapping.json") > 0.5) {
        {
            if (!(ds_map_exists(global.gmlgamepadMapping, string(arguments[2 + 0])) > 0.5)) {
                {
                    return arguments[2 + 0];
                }
            } else {
                if (ds_map_find_value(global.gmlgamepadMapping, string(arguments[2 + 0])) == "") {
                    {
                        return arguments[2 + 0];
                    }
                } else {
                    {
                        return string_upper(ds_map_find_value(global.gmlgamepadMapping, string(arguments[2 + 0])));
                    }
                }
            }
        }
    } else {
        {
            if (!(global.gmlhtml5Build > 0.5)) {
                {
                    var gmlgamepadDesc = gamepad_get_description(global.gmljoyid);
                    switch (arguments[2 + 0]) {
                        case 32769:
                            return "A";
                        case 32770:
                            return "B";
                        case 32771:
                            return "X";
                        case 32772:
                            return "Y";
                        case 32778:
                            return "START";
                        case 32777:
                            return "BACK";
                        case 32779:
                            return "LSTICK";
                        case 32780:
                            return "RSTICK";
                        case 32773:
                            return "LB";
                        case 32774:
                            return "RB";
                        case 32775:
                            return "LT";
                        case 32776:
                            return "RT";
                        case 32783:
                            return "LEFT";
                        case 32784:
                            return "RIGHT";
                        case 32781:
                            return "UP";
                        case 32782:
                            return "DOWN";
                        default:
                            return string(arguments[2 + 0]);
                    }
                }
            } else {
                {
                    return string(html5_gamepad_get_button_name(global.gmljoyid, arguments[2 + 0]));
                }
            }
        }
    }
}

