function gml_Script_drawTouchControls(_inst, _other) {
    _inst.gmlscale_level = global.gmldisplay_h / 240;
    _inst.gmlvkey_size = 32 * _inst.gmlscale_level;
    if (instance_exists(433) > 0.5 && yyInst(433).gmlpaused > 0.5) {
        {
            _inst.gmlposX = 0;
            _inst.gmlposY = 0;
        }
    } else {
        {
            if (global.gmlhtml5Build > 0.5) {
                {
                    _inst.gmlposX = g_pBuiltIn.view_xview[~~0];
                    _inst.gmlposY = g_pBuiltIn.view_yview[~~0];
                }
            } else {
                {
                    _inst.gmlposX = 0;
                    _inst.gmlposY = 0;
                }
            }
        }
    }
    if (global.gmltouchControlsVisibility == 1) {
        {
            draw_sprite(_inst, 819, -1, _inst.gmlposX, _inst.gmlposY + global.gmldisplay_h - 3 * _inst.gmlvkey_size);
            draw_sprite(_inst, 820, -1, _inst.gmlposX + global.gmldisplay_w - 2.5 * _inst.gmlvkey_size, _inst.gmlposY + global.gmldisplay_h - 2.5 * _inst.gmlvkey_size);
            if (instance_exists(433) > 0.5 && !(yyInst(433).gmlpaused > 0.5)) {
                {
                    draw_sprite(_inst, 821, -1, _inst.gmlposX + global.gmldisplay_w - _inst.gmlvkey_size, _inst.gmlposY);
                }
            } else {
                {
                    draw_sprite(_inst, 822, -1, _inst.gmlposX + global.gmldisplay_w - _inst.gmlvkey_size, _inst.gmlposY);
                }
            }
            if (global.gmldebugBuild > 0.5) {
                {
                    draw_sprite(_inst, 828, -1, _inst.gmlposX, _inst.gmlposY + _inst.gmlvkey_size);
                    draw_sprite(_inst, 828, -1, _inst.gmlposX, _inst.gmlposY + 2 * _inst.gmlvkey_size);
                    draw_sprite(_inst, 828, -1, _inst.gmlposX, _inst.gmlposY + 3 * _inst.gmlvkey_size);
                    draw_sprite(_inst, 828, -1, _inst.gmlposX + _inst.gmlvkey_size, _inst.gmlposY + 3 * _inst.gmlvkey_size);
                }
            }
        }
    } else {
        if (global.gmltouchControlsVisibility == 2) {
            {
                draw_sprite(_inst, 823, -1, _inst.gmlposX, _inst.gmlposY + global.gmldisplay_h - 3 * _inst.gmlvkey_size);
                draw_sprite(_inst, 824, -1, _inst.gmlposX + global.gmldisplay_w - 2.5 * _inst.gmlvkey_size, _inst.gmlposY + global.gmldisplay_h - 2.5 * _inst.gmlvkey_size);
                if (instance_exists(433) > 0.5 && !(yyInst(433).gmlpaused > 0.5)) {
                    {
                        draw_sprite(_inst, 825, -1, _inst.gmlposX + global.gmldisplay_w - _inst.gmlvkey_size, _inst.gmlposY);
                    }
                } else {
                    {
                        draw_sprite(_inst, 826, -1, _inst.gmlposX + global.gmldisplay_w - _inst.gmlvkey_size, _inst.gmlposY);
                    }
                }
                if (global.gmldebugBuild > 0.5) {
                    {
                        draw_sprite(_inst, 827, -1, _inst.gmlposX, _inst.gmlposY + _inst.gmlvkey_size);
                        draw_sprite(_inst, 827, -1, _inst.gmlposX, _inst.gmlposY + 2 * _inst.gmlvkey_size);
                        draw_sprite(_inst, 827, -1, _inst.gmlposX, _inst.gmlposY + 3 * _inst.gmlvkey_size);
                        draw_sprite(_inst, 827, -1, _inst.gmlposX + _inst.gmlvkey_size, _inst.gmlposY + 3 * _inst.gmlvkey_size);
                    }
                }
            }
        }
    }
}

