// ini_write_string("highscore", "name"+string(argument0),argument1)
// ini_write_real(  "highscore","value"+string(argument0),argument2)
//
function gml_Script_highscore_add2(_inst, _other, argument0, argument1, argument2) {
    ini_write_string("highscore", "name" + string(argument0), argument1);
    ini_write_real("highscore", "value" + string(argument0), argument2);
}

// #####################################################################################################
// if os_browser==browser_not_a_browser
// {
//     game_end()
// }
// else
// {
//     sound_stop_all()
//     game_restart()
// }
//
function gml_Script_game_end2(_inst, _other) {
    if (g_pBuiltIn.get_os_browser() == -1) {
        {
            game_end();
        }
    } else {
        {
            sound_stop_all();
            game_restart();
        }
    }
}

