function gml_Script_setLocale(_inst, _other) {
    if (global.gmlfirstLaunch > 0.5) {
        {
            var gmlosLocale = os_get_language();
            if (ds_map_exists(global.gmllocalesMap, gmlosLocale) > 0.5) {
                {
                    global.gmllocale = gmlosLocale;
                }
            }
            gml_Script_configSave(_inst, _other);
        }
    }
    var gmllocaleDir = g_pBuiltIn.working_directory + "locale/locales/" + global.gmllocale;
    var gmlcharsetDir = gmllocaleDir + "/charset/";
    if (file_exists(gmlcharsetDir + "charset") > 0.5 && file_exists(gmlcharsetDir + "charset.png") > 0.5 && file_exists(gmlcharsetDir + "charset_small.png") > 0.5) {
        {
            var gmlcharsetFile = file_text_open_read(gmlcharsetDir + "charset");
            _inst.gmlcharset = file_text_read_string(gmlcharsetFile);
            file_text_close(gmlcharsetFile);
            _inst.gmlchars_n = string_length(_inst.gmlcharset);
            _inst.gmlfontSprite = sprite_add(gmlcharsetDir + "charset.png", _inst.gmlchars_n, 0, 0, 0, 0);
            _inst.gmlfontSpriteSmall = sprite_add(gmlcharsetDir + "charset_small.png", _inst.gmlchars_n, 0, 0, 0, 0);
            if (file_exists(gmlcharsetDir + "font.json") > 0.5) {
                {
                    _inst.gmlfontInfo = gml_Script_json2dsmap(_inst, _other, gmlcharsetDir + "font.json");
                    global.gmlfontSmallWidth = ds_map_find_value(_inst.gmlfontInfo, "fontSmallWidth");
                    global.gmlfontSmallHeight = ds_map_find_value(_inst.gmlfontInfo, "fontSmallHeight");
                    global.gmlfontLargeWidth = ds_map_find_value(_inst.gmlfontInfo, "fontLargeWidth");
                    global.gmlfontLargeHeight = ds_map_find_value(_inst.gmlfontInfo, "fontLargeHeight");
                    global.gmlfontOffsetY = ds_map_find_value(_inst.gmlfontInfo, "fontOffsetY");
                    ds_map_destroy(_inst.gmlfontInfo);
                }
            } else {
                {
                    global.gmlfontSmallWidth = 8;
                    global.gmlfontSmallHeight = 8;
                    global.gmlfontLargeWidth = 16;
                    global.gmlfontLargeHeight = 16;
                    global.gmlfontOffsetY = 0;
                }
            }
            global.gmlmessageBackground = 0 ? 1 : 0;
            global.gmlfontLarge = font_add_sprite_ext(_inst.gmlfontSprite, _inst.gmlcharset, 0, 0);
            global.gmlfontSmall = font_add_sprite_ext(_inst.gmlfontSpriteSmall, _inst.gmlcharset, 0, 0);
        }
    } else {
        {
            if (file_exists(gmllocaleDir + "/font.json") > 0.5) {
                {
                    _inst.gmlfontInfo = gml_Script_json2dsmap(_inst, _other, gmllocaleDir + "/font.json");
                    _inst.gmlfontName = ds_map_find_value(_inst.gmlfontInfo, "fontName");
                }
            } else {
                {
                    _inst.gmlfont = gml_Script_json2dsmap(_inst, _other, g_pBuiltIn.working_directory + "locale/fonts.json");
                    _inst.gmlfontName = ds_map_find_value(_inst.gmlfont, "fontName");
                    ds_map_destroy(_inst.gmlfont);
                    _inst.gmlfontInfo = gml_Script_json2dsmap(_inst, _other, g_pBuiltIn.working_directory + "locale/fonts/" + _inst.gmlfontName + "/font.json");
                }
            }
            _inst.gmlfontDir = g_pBuiltIn.working_directory + "locale/fonts/" + _inst.gmlfontName + "/font/";
            if (!(global.gmlhtml5Build > 0.5)) {
                {
                    _inst.gmlfontName = _inst.gmlfontName + ".ttf";
                }
            } else {
                {
                    _inst.gmlfontName = _inst.gmlfontName + ".woff";
                }
            }
            _inst.gmlfontPath = _inst.gmlfontDir + _inst.gmlfontName;
            global.gmlfontSmallWidth = int64(ds_map_find_value(_inst.gmlfontInfo, "fontWidth"));
            global.gmlfontSmallHeight = int64(ds_map_find_value(_inst.gmlfontInfo, "fontHeight"));
            global.gmlfontOffsetY = int64(ds_map_find_value(_inst.gmlfontInfo, "fontOffsetY"));
            global.gmlmessageBackground = bool(ds_map_find_value(_inst.gmlfontInfo, "messageBackground"));
            global.gmlfontLargeWidth = global.gmlfontSmallWidth * 2;
            global.gmlfontLargeHeight = global.gmlfontSmallHeight * 2;
            global.gmlfontLarge = font_add(_inst.gmlfontPath, global.gmlfontLargeHeight, 0, 0, 0, 255);
            global.gmlfontSmall = font_add(_inst.gmlfontPath, global.gmlfontSmallHeight, 0, 0, 0, 255);
            ds_map_destroy(_inst.gmlfontInfo);
        }
    }
    var gmllocalizedTextFile = gmllocaleDir + "/text.json";
    global.gmllocalizedTextMap = gml_Script_json2dsmap(_inst, _other, gmllocalizedTextFile);
}

// #####################################################################################################
// ///tr(key)
// if (!ds_map_exists(global.localizedTextMap, argument[0])) {
//     return argument[0];
// } else if (global.localizedTextMap[? argument[0]] == "") {
//     return argument[0];
// } else {
//     return string_upper(global.localizedTextMap[? argument[0]]);
// }
//
function gml_Script_tr(_inst, _other) {
    if (!(ds_map_exists(global.gmllocalizedTextMap, arguments[2 + 0]) > 0.5)) {
        {
            return arguments[2 + 0];
        }
    } else {
        if (ds_map_find_value(global.gmllocalizedTextMap, arguments[2 + 0]) == "") {
            {
                return arguments[2 + 0];
            }
        } else {
            {
                return string_upper(ds_map_find_value(global.gmllocalizedTextMap, arguments[2 + 0]));
            }
        }
    }
}

// #####################################################################################################
// ///json2dsmap(filepath)
//
// var filepath = argument[0];
//
// var i = 0;
// var data = "";
// var file = file_text_open_read(filepath);
// while (!file_text_eof(file)) {
//     data += file_text_read_string(file);
//     file_text_readln(file);
// }
// file_text_close(file);
// map = json_decode(data);
//
// return map;
//
function gml_Script_json2dsmap(_inst, _other) {
    var gmlfilepath = arguments[2 + 0];
    var gmli = 0;
    var gmldata = "";
    var gmlfile = file_text_open_read(gmlfilepath);
    while (!(file_text_eof(gmlfile) > 0.5)) {
        {
            gmldata += file_text_read_string(gmlfile);
            file_text_readln(gmlfile);
        }
    }
    file_text_close(gmlfile);
    _inst.gmlmap = json_decode(gmldata);
    return _inst.gmlmap;
}

// #####################################################################################################
// ///dsmap2json(map, filepath)
//
// var map = argument[0];
// var filepath = argument[1];
//
// str = json_encode(map);
// file = file_text_open_write(filepath);
// file_text_write_string(file, str);
// file_text_close(file);
//
function gml_Script_dsmap2json(_inst, _other) {
    var gmlmap = arguments[2 + 0];
    var gmlfilepath = arguments[2 + 1];
    _inst.gmlstr = json_encode(gmlmap);
    _inst.gmlfile = file_text_open_write(gmlfilepath);
    file_text_write_string(_inst.gmlfile, _inst.gmlstr);
    file_text_close(_inst.gmlfile);
}

