function gml_Script_configLoad(_inst, _other) {
    global.gmlkeyUpVal = 38;
    global.gmlkeyDownVal = 40;
    global.gmlkeyLeftVal = 37;
    global.gmlkeyRightVal = 39;
    global.gmlkeyJumpVal = 90;
    global.gmlkeyAttackVal = 88;
    global.gmlkeyItemVal = 67;
    global.gmlkeyRunVal = 16;
    global.gmlkeyBombVal = 65;
    global.gmlkeyRopeVal = 83;
    global.gmlkeyFlareVal = 70;
    global.gmlkeyPayVal = 80;
    global.gmlkeyStartVal = 27;
    global.gmlkeyEscape = 27;
    global.gmlkeyEnter = 13;
    if (g_pBuiltIn.get_os_type() == 4) {
        {
            global.gmlkeyStartVal = 8;
            global.gmlkeyEscape = 8;
            global.gmlkeyEnter = 10;
        }
    }
    if (!(global.gmlhtml5Build > 0.5)) {
        {
            global.gmljoyJumpVal = 32769;
            global.gmljoyAttackVal = 32770;
            global.gmljoyItemVal = 32771;
            global.gmljoyRunVal = 32775;
            global.gmljoyBombVal = 32773;
            global.gmljoyRopeVal = 32774;
            global.gmljoyFlareVal = 32772;
            global.gmljoyPayVal = 32776;
            global.gmljoyStartVal = 32778;
        }
    } else {
        {
            global.gmljoyAttackVal = 0;
            global.gmljoyJumpVal = 1;
            global.gmljoyItemVal = 2;
            global.gmljoyRunVal = 3;
            global.gmljoyFlareVal = 4;
            global.gmljoyPayVal = 5;
            global.gmljoyBombVal = 6;
            global.gmljoyRopeVal = 7;
            global.gmljoyStartVal = 9;
        }
    }
    if (file_exists(g_pBuiltIn.working_directory + "settings.json") > 0.5) {
        {
            var gmlsettingsMap = gml_Script_json2dsmap(_inst, _other, g_pBuiltIn.working_directory + "settings.json");
            global.gmllocale = ds_map_find_value(gmlsettingsMap, "locale");
            global.gmlfullscreen = ds_map_find_value(gmlsettingsMap, "fullscreen");
            global.gmlmusic = ds_map_find_value(gmlsettingsMap, "music");
            global.gmltoggleRunEnabled = ds_map_find_value(gmlsettingsMap, "toggleRunEnabled");
            global.gmlfirstLaunch = ds_map_find_value(gmlsettingsMap, "firstLaunch");
            global.gmltouchControlsVisibility = int64(ds_map_find_value(gmlsettingsMap, "touchControlsVisibility"));
            ds_map_destroy(gmlsettingsMap);
        }
    }
    if (file_exists(g_pBuiltIn.working_directory + "keys.json") > 0.5) {
        {
            var gmlkeysMap = gml_Script_json2dsmap(_inst, _other, g_pBuiltIn.working_directory + "keys.json");
            global.gmlkeyUpVal = int64(ds_map_find_value(gmlkeysMap, "keyUpVal"));
            global.gmlkeyDownVal = int64(ds_map_find_value(gmlkeysMap, "keyDownVal"));
            global.gmlkeyLeftVal = int64(ds_map_find_value(gmlkeysMap, "keyLeftVal"));
            global.gmlkeyRightVal = int64(ds_map_find_value(gmlkeysMap, "keyRightVal"));
            global.gmlkeyJumpVal = int64(ds_map_find_value(gmlkeysMap, "keyJumpVal"));
            global.gmlkeyAttackVal = int64(ds_map_find_value(gmlkeysMap, "keyAttackVal"));
            global.gmlkeyItemVal = int64(ds_map_find_value(gmlkeysMap, "keyItemVal"));
            global.gmlkeyRunVal = int64(ds_map_find_value(gmlkeysMap, "keyRunVal"));
            global.gmlkeyBombVal = int64(ds_map_find_value(gmlkeysMap, "keyBombVal"));
            global.gmlkeyRopeVal = int64(ds_map_find_value(gmlkeysMap, "keyRopeVal"));
            global.gmlkeyFlareVal = int64(ds_map_find_value(gmlkeysMap, "keyFlareVal"));
            global.gmlkeyPayVal = int64(ds_map_find_value(gmlkeysMap, "keyPayVal"));
            ds_map_destroy(gmlkeysMap);
        }
    }
    if (file_exists(g_pBuiltIn.working_directory + "gamepad.json") > 0.5) {
        {
            var gmljoyMap = gml_Script_json2dsmap(_inst, _other, g_pBuiltIn.working_directory + "gamepad.json");
            global.gmljoyJumpVal = int64(ds_map_find_value(gmljoyMap, "joyJumpVal"));
            global.gmljoyAttackVal = int64(ds_map_find_value(gmljoyMap, "joyAttackVal"));
            global.gmljoyItemVal = int64(ds_map_find_value(gmljoyMap, "joyItemVal"));
            global.gmljoyRunVal = int64(ds_map_find_value(gmljoyMap, "joyRunVal"));
            global.gmljoyBombVal = int64(ds_map_find_value(gmljoyMap, "joyBombVal"));
            global.gmljoyRopeVal = int64(ds_map_find_value(gmljoyMap, "joyRopeVal"));
            global.gmljoyFlareVal = int64(ds_map_find_value(gmljoyMap, "joyFlareVal"));
            global.gmljoyPayVal = int64(ds_map_find_value(gmljoyMap, "joyPayVal"));
            global.gmljoyStartVal = int64(ds_map_find_value(gmljoyMap, "joyStartVal"));
            ds_map_destroy(gmljoyMap);
        }
    }
    if (file_exists(g_pBuiltIn.working_directory + "gamepadmapping.json") > 0.5) {
        {
            global.gmlgamepadMapping = gml_Script_json2dsmap(_inst, _other, g_pBuiltIn.working_directory + "gamepadmapping.json");
        }
    } else {
        {
            global.gmlgamepadMapping = ds_map_create();
        }
    }
}

