function gml_Script_configSave(_inst, _other) {
    if (file_exists(g_pBuiltIn.working_directory + "settings.json") > 0.5) {
        {
            var gmlsettingsMap = gml_Script_json2dsmap(_inst, _other, g_pBuiltIn.working_directory + "settings.json");
        }
    } else {
        {
            var gmlsettingsMap = ds_map_create();
        }
    }
    ds_map_replace(gmlsettingsMap, "locale", global.gmllocale);
    if (!(global.gmlhtml5Build > 0.5)) {
        {
            ds_map_replace(gmlsettingsMap, "fullscreen", bool(global.gmlfullscreen));
            ds_map_replace(gmlsettingsMap, "music", bool(global.gmlmusic));
            ds_map_replace(gmlsettingsMap, "toggleRunEnabled", bool(global.gmltoggleRunEnabled));
            ds_map_replace(gmlsettingsMap, "firstLaunch", bool(global.gmlfirstLaunch));
        }
    } else {
        {
            ds_map_replace(gmlsettingsMap, "fullscreen", global.gmlfullscreen);
            ds_map_replace(gmlsettingsMap, "music", global.gmlmusic);
            ds_map_replace(gmlsettingsMap, "toggleRunEnabled", global.gmltoggleRunEnabled);
            ds_map_replace(gmlsettingsMap, "firstLaunch", global.gmlfirstLaunch);
        }
    }
    ds_map_replace(gmlsettingsMap, "touchControlsVisibility", int64(global.gmltouchControlsVisibility));
    gml_Script_dsmap2json(_inst, _other, gmlsettingsMap, g_pBuiltIn.working_directory + "settings.json");
    ds_map_destroy(gmlsettingsMap);
}

