//
// dsmap2json(joyMap, working_directory + "gamepad.json");
// ds_map_destroy(joyMap);
//
function gml_Script_joySave(_inst, _other) {
    if (file_exists(g_pBuiltIn.working_directory + "gamepad.json") > 0.5) {
        {
            var gmljoyMap = gml_Script_json2dsmap(_inst, _other, g_pBuiltIn.working_directory + "gamepad.json");
        }
    } else {
        {
            var gmljoyMap = ds_map_create();
        }
    }
    ds_map_replace(gmljoyMap, "joyJumpVal", int64(global.gmljoyJumpVal));
    ds_map_replace(gmljoyMap, "joyAttackVal", int64(global.gmljoyAttackVal));
    ds_map_replace(gmljoyMap, "joyItemVal", int64(global.gmljoyItemVal));
    ds_map_replace(gmljoyMap, "joyRunVal", int64(global.gmljoyRunVal));
    ds_map_replace(gmljoyMap, "joyBombVal", int64(global.gmljoyBombVal));
    ds_map_replace(gmljoyMap, "joyRopeVal", int64(global.gmljoyRopeVal));
    ds_map_replace(gmljoyMap, "joyFlareVal", int64(global.gmljoyFlareVal));
    ds_map_replace(gmljoyMap, "joyPayVal", int64(global.gmljoyPayVal));
    ds_map_replace(gmljoyMap, "joyStartVal", int64(global.gmljoyStartVal));
    gml_Script_dsmap2json(_inst, _other, gmljoyMap, g_pBuiltIn.working_directory + "gamepad.json");
    ds_map_destroy(gmljoyMap);
}

