// ///menuToggleFullscreen
//
// global.fullscreen = !global.fullscreen;
// if (global.fullscreen) {
//     if (!global.html5Build) {
//         window_set_fullscreen(true);
//     } else {
//         if (global.electronBuild) {
//             newSize = electronSetFullscreen(true);
//             window_set_size(newSize[0], newSize[1]);
//         } else if (global.browserBuild) {
//             newSize = html5_set_fullscreen(true);
//             window_set_size(newSize[0], newSize[1]);
//         }
//     }
// } else {
//     if (!global.html5Build) {
//         window_set_fullscreen(false);
//         window_set_size(800, 800/(display_get_width()/display_get_height()));
//     } else {
//         if (global.electronBuild) {
//             newSize = electronSetFullscreen(false);
//             window_set_size(newSize[0], newSize[1]);
//         } else if (global.browserBuild) {
//             newSize = html5_set_fullscreen(false);
//             window_set_size(newSize[0], newSize[1]);
//         }
//     }
// }
//
function gml_Script_menuToggleFullscreen(_inst, _other) {
    global.gmlfullscreen = !(global.gmlfullscreen > 0.5) ? 1 : 0;
    if (global.gmlfullscreen > 0.5) {
        {
            if (!(global.gmlhtml5Build > 0.5)) {
                {
                    window_set_fullscreen(1);
                }
            } else {
                {
                    if (global.gmlelectronBuild > 0.5) {
                        {
                            _inst.gmlnewSize = electronSetFullscreen(1);
                            window_set_size(_inst.gmlnewSize[~~0], _inst.gmlnewSize[~~1]);
                        }
                    } else {
                        if (global.gmlbrowserBuild > 0.5) {
                            {
                                _inst.gmlnewSize = html5_set_fullscreen(1);
                                window_set_size(_inst.gmlnewSize[~~0], _inst.gmlnewSize[~~1]);
                            }
                        }
                    }
                }
            }
        }
    } else {
        {
            if (!(global.gmlhtml5Build > 0.5)) {
                {
                    window_set_fullscreen(0);
                    window_set_size(800, 800 / (display_get_width() / display_get_height()));
                }
            } else {
                {
                    if (global.gmlelectronBuild > 0.5) {
                        {
                            _inst.gmlnewSize = electronSetFullscreen(0);
                            window_set_size(_inst.gmlnewSize[~~0], _inst.gmlnewSize[~~1]);
                        }
                    } else {
                        if (global.gmlbrowserBuild > 0.5) {
                            {
                                _inst.gmlnewSize = html5_set_fullscreen(0);
                                window_set_size(_inst.gmlnewSize[~~0], _inst.gmlnewSize[~~1]);
                            }
                        }
                    }
                }
            }
        }
    }
}

// #####################################################################################################
// ///menuLanguage
// if (!global.html5Build) {
//     instance_activate_all();
//     changeLocale();
//     setLocale();
//     loadLocalizedSprites();
//     instance_deactivate_all(true);
// } else {
//     changeLocale();
//     localeChanged = true;
//     changeSprites = true;
// }
//
function gml_Script_menuLanguage(_inst, _other) {
    if (!(global.gmlhtml5Build > 0.5)) {
        {
            instance_activate_all(_inst);
            gml_Script_changeLocale(_inst, _other);
            gml_Script_setLocale(_inst, _other);
            gml_Script_loadLocalizedSprites(_inst, _other);
            instance_deactivate_all(_inst, 1);
        }
    } else {
        {
            gml_Script_changeLocale(_inst, _other);
            _inst.gmllocaleChanged = 1 ? 1 : 0;
            _inst.gmlchangeSprites = 1 ? 1 : 0;
        }
    }
}

// #####################################################################################################
// ///quitGame
//
// if (!global.html5Build) {
//     game_end();
// } else {
//     if (global.electronBuild) {
//         electronQuit();
//     }
// }
//
function gml_Script_quitGame(_inst, _other) {
    if (!(global.gmlhtml5Build > 0.5)) {
        {
            game_end();
        }
    } else {
        {
            if (global.gmlelectronBuild > 0.5) {
                {
                    electronQuit();
                }
            }
        }
    }
}

// #####################################################################################################
// ///toggleMusic
// global.music = !global.music;
// onOffMusic();
//
function gml_Script_toggleMusic(_inst, _other) {
    global.gmlmusic = !(global.gmlmusic > 0.5) ? 1 : 0;
    gml_Script_onOffMusic(_inst, _other);
}

// #####################################################################################################
// ///onOffMusic
// if (!global.music) {
//     stopAllMusic();
// } else {
//     if (isLevel()) {
//         if (global.levelType == 1) playMusic(global.musLush, true);
//         else if (global.levelType == 2) playMusic(global.musIce, true);
//         else if (global.levelType == 3) playMusic(global.musTemple, true);
//         else if (isRoom("rOlmec")){
//             if (oPlayer1.active) playMusic(global.musBoss, true);
//         } else playMusic(global.musCave, true);
//     } else if (isRoom("rTitle")) playMusic(global.musTitle, true);
// }
//
function gml_Script_onOffMusic(_inst, _other) {
    if (!(global.gmlmusic > 0.5)) {
        {
            gml_Script_stopAllMusic(_inst, _other);
        }
    } else {
        {
            if (gml_Script_isLevel(_inst, _other) > 0.5) {
                {
                    if (global.gmllevelType == 1) {
                        gml_Script_playMusic(_inst, _other, global.gmlmusLush, 1);
                    } else {
                        if (global.gmllevelType == 2) {
                            gml_Script_playMusic(_inst, _other, global.gmlmusIce, 1);
                        } else {
                            if (global.gmllevelType == 3) {
                                gml_Script_playMusic(_inst, _other, global.gmlmusTemple, 1);
                            } else {
                                if (gml_Script_isRoom(_inst, _other, "rOlmec") > 0.5) {
                                    {
                                        if (yyInst(454).gmlactive > 0.5) {
                                            gml_Script_playMusic(_inst, _other, global.gmlmusBoss, 1);
                                        }
                                    }
                                } else {
                                    gml_Script_playMusic(_inst, _other, global.gmlmusCave, 1);
                                }
                            }
                        }
                    }
                }
            } else {
                if (gml_Script_isRoom(_inst, _other, "rTitle") > 0.5) {
                    gml_Script_playMusic(_inst, _other, global.gmlmusTitle, 1);
                }
            }
        }
    }
}

