function gml_Object_oDarkFall_Step_0(_inst, _other) {
    {
        action_inherited(_inst, _other);
        if (gml_Script_isCollisionCharacterTop(_inst, _other, 1, 0) > 0.5) {
            {
                _inst.gmltimeFall -= 1;
                if (_inst.gmltimeFall <= 0) {
                    _inst.gmlyAcc = _inst.gmlgrav;
                }
            }
        } else {
            if (_inst.gmltimeFall < _inst.gmltimeFallMax) {
                _inst.gmltimeFall += 1;
            }
        }
        if (_inst.gmlyVel > 10) {
            _inst.gmlyVel = 10;
        }
    }
}

