function gml_Object_oShopkeeper_Create_0(_inst, _other) {
    {
        action_inherited(_inst, _other);
        gml_Script_makeActive(_inst, _other);
        gml_Script_setCollisionBounds(_inst, _other, 2, 0, _inst.get_sprite_width() - 2, _inst.get_sprite_height());
        _inst.gmlxVel = 0;
        _inst.image_speed = 0.5;
        _inst.gmlmyGrav = 0.6;
        _inst.gmltype = "Shopkeeper";
        _inst.gmlstyle = "General";
        _inst.gmlhp = 20;
        _inst.gmlinvincible = 0;
        _inst.gmlfavor = 12;
        _inst.gmlIDLE = 0;
        _inst.gmlWALK = 1;
        _inst.gmlATTACK = 2;
        _inst.gmlTHROW = 3;
        _inst.gmlPATROL = 4;
        _inst.gmlFOLLOW = 5;
        _inst.gmlSTUNNED = 98;
        _inst.gmlDEAD = 99;
        _inst.gmlstatus = 0;
        _inst.gmlwhipped = 0 ? 1 : 0;
        _inst.gmlbounced = 0 ? 1 : 0;
        _inst.gmldead = 0 ? 1 : 0;
        _inst.gmlcounter = 0;
        _inst.gmlsightCounter = 0;
        _inst.gmlturnTimer = 0;
        _inst.gmlthrowCount = 0;
        _inst.gmlstunTime = 5;
        _inst.gmlbetValue = 1000 + global.gmlcurrLevel * 500;
        _inst.gmlLEFT = 0;
        _inst.gmlRIGHT = 1;
        _inst.gmlfacing = _inst.gmlLEFT;
        _inst.gmlshakeCounter = 0;
        _inst.gmlshakeToggle = 1;
        _inst.gmlwelcomed = 0 ? 1 : 0;
        _inst.gmlangered = 0 ? 1 : 0;
        _inst.gmlhasGun = 1 ? 1 : 0;
        _inst.gmlfiring = 0;
        _inst.gmlfiringMax = 30;
    }
}

