//     global.joyid = pad_ind;
//     gamepad_set_button_threshold(global.joyid, 1); // we need this to be pretty high, as analogue triggers are treated like analogue triggers and not like buttons!
// }
// else
// {
//     global.gamepadOn = false;
//     global.joyid = -1;
// }
//
// /* */
// /*  */ }
//
function gml_Object_oGamepad_Other_75(_inst, _other) {
    {
        var gmlev_type = ds_map_find_value(g_pBuiltIn.get_async_load(), "event_type");
        var gmlpad_ind = ds_map_find_value(g_pBuiltIn.get_async_load(), "pad_index");
        if (gmlev_type == "gamepad discovered") {
            {
                global.gmlgamepadOn = 1 ? 1 : 0;
                global.gmljoyid = gmlpad_ind;
                gamepad_set_button_threshold(global.gmljoyid, 1);
            }
        } else {
            {
                global.gmlgamepadOn = 0 ? 1 : 0;
                global.gmljoyid = -1;
            }
        }
    }
}

