//
// status += 1;
// if (status > 10) room_goto(rTitle);
//
// /* */
// /*  */ }
//
function gml_Object_oKeyConfig_KeyPress_1(_inst, _other) {
    {
        var gmlpressedKey;
        if (!(global.gmlmobileBuild > 0.5)) {
            {
                gmlpressedKey = g_pBuiltIn.keyboard_key;
            }
        } else {
            {
                gmlpressedKey = global.gmlkeyEscape;
                for (var gmli = 2; gmli < 256; gmli++) {
                    {
                        if (keyboard_check_pressed(gmli) > 0.5) {
                            {
                                gmlpressedKey = gmli;
                            }
                        }
                    }
                }
            }
        }
        if (gmlpressedKey != global.gmlkeyEscape) {
            {
                if (_inst.gmlstatus == 0) {
                    {
                        global.gmlkeyUpVal = gmlpressedKey;
                    }
                } else {
                    if (_inst.gmlstatus == 1) {
                        {
                            global.gmlkeyDownVal = gmlpressedKey;
                        }
                    } else {
                        if (_inst.gmlstatus == 2) {
                            {
                                global.gmlkeyLeftVal = gmlpressedKey;
                            }
                        } else {
                            if (_inst.gmlstatus == 3) {
                                {
                                    global.gmlkeyRightVal = gmlpressedKey;
                                }
                            } else {
                                if (_inst.gmlstatus == 4) {
                                    {
                                        global.gmlkeyJumpVal = gmlpressedKey;
                                    }
                                } else {
                                    if (_inst.gmlstatus == 5) {
                                        {
                                            global.gmlkeyAttackVal = gmlpressedKey;
                                        }
                                    } else {
                                        if (_inst.gmlstatus == 6) {
                                            {
                                                global.gmlkeyItemVal = gmlpressedKey;
                                            }
                                        } else {
                                            if (_inst.gmlstatus == 7) {
                                                {
                                                    global.gmlkeyRunVal = gmlpressedKey;
                                                }
                                            } else {
                                                if (_inst.gmlstatus == 8) {
                                                    {
                                                        global.gmlkeyBombVal = gmlpressedKey;
                                                    }
                                                } else {
                                                    if (_inst.gmlstatus == 9) {
                                                        {
                                                            global.gmlkeyRopeVal = gmlpressedKey;
                                                        }
                                                    } else {
                                                        if (_inst.gmlstatus == 10) {
                                                            {
                                                                global.gmlkeyPayVal = gmlpressedKey;
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        _inst.gmlstatus += 1;
        if (_inst.gmlstatus > 10) {
            room_goto(5);
        }
    }
}

