//     if (gamepad.startPressed) gamepad.startPressed = false;
//     if (status > 7) room_goto(rTitle);
// }
//
// /* */
// /*  */ }
//
function gml_Object_oJoyConfig_Step_0(_inst, _other) {
    {
        _inst.gmljoyReleased = 0 ? 1 : 0;
        _inst.gmljoyPressed = 0 ? 1 : 0;
        _inst.gmljoyKey = gml_Script_checkJoyButton(_inst, _other);
        if (_inst.gmljoy > 0.5) {
            {
                if (_inst.gmljoyKey != 0) {
                    {
                        _inst.gmljoy = 1 ? 1 : 0;
                    }
                } else {
                    {
                        _inst.gmljoyReleased = 1 ? 1 : 0;
                        _inst.gmljoy = 0 ? 1 : 0;
                    }
                }
            }
        } else {
            {
                if (_inst.gmljoyKey != 0) {
                    {
                        _inst.gmljoyPressed = 1 ? 1 : 0;
                        _inst.gmljoy = 1 ? 1 : 0;
                    }
                } else {
                    {
                        _inst.gmljoy = 0 ? 1 : 0;
                    }
                }
            }
        }
        if (_inst.gmljoyPressed > 0.5) {
            {
                if (_inst.gmlstatus == 0) {
                    {
                        global.gmljoyJumpVal = _inst.gmljoyKey;
                    }
                } else {
                    if (_inst.gmlstatus == 1) {
                        {
                            global.gmljoyAttackVal = _inst.gmljoyKey;
                        }
                    } else {
                        if (_inst.gmlstatus == 2) {
                            {
                                global.gmljoyItemVal = _inst.gmljoyKey;
                            }
                        } else {
                            if (_inst.gmlstatus == 3) {
                                {
                                    global.gmljoyRunVal = _inst.gmljoyKey;
                                }
                            } else {
                                if (_inst.gmlstatus == 4) {
                                    {
                                        global.gmljoyBombVal = _inst.gmljoyKey;
                                    }
                                } else {
                                    if (_inst.gmlstatus == 5) {
                                        {
                                            global.gmljoyRopeVal = _inst.gmljoyKey;
                                        }
                                    } else {
                                        if (_inst.gmlstatus == 6) {
                                            {
                                                global.gmljoyPayVal = _inst.gmljoyKey;
                                            }
                                        } else {
                                            if (_inst.gmlstatus == 7) {
                                                {
                                                    global.gmljoyStartVal = _inst.gmljoyKey;
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        if (_inst.gmljoyPressed > 0.5 || keyboard_check_pressed(27) > 0.5) {
            {
                _inst.gmlstatus += 1;
                if (yyInst(global.gmlgamepad).gmlattackPressed > 0.5) {
                    yyInst(global.gmlgamepad).gmlattackPressed = 0 ? 1 : 0;
                }
                if (yyInst(global.gmlgamepad).gmlstartPressed > 0.5) {
                    yyInst(global.gmlgamepad).gmlstartPressed = 0 ? 1 : 0;
                }
                if (_inst.gmlstatus > 7) {
                    room_goto(5);
                }
            }
        }
    }
}

