function gml_Object_oJoyConfigHtml5_Alarm_0(_inst, _other) {
    {
        _inst.gmlbuttonPressed = 0 ? 1 : 0;
        if (!(html5_gamepad_button_check(global.gmljoyid, _inst.gmlbutton) > 0.5)) {
            {
                _inst.gmlbuttonPreviousState = 0 ? 1 : 0;
            }
        }
    }
}

