//
function gml_Object_oJoyConfigHtml5_Step_0(_inst, _other) {
    {
        for (var gmli = 0; gmli < 31; gmli++) {
            {
                if (html5_gamepad_button_check(global.gmljoyid, gmli) > 0.5) {
                    {
                        if (_inst.gmlbuttonPreviousState == 0) {
                            {
                                _inst.gmlbuttonPressed = 1 ? 1 : 0;
                                _inst.gmlbuttonPreviousState = 1 ? 1 : 0;
                                _inst.gmlbutton = gmli;
                            }
                        }
                    }
                }
            }
        }
        if (!(_inst.alarm instanceof Array)) {
            _inst.alarm = [];
            _inst.alarm.__yy_owner = 1584050178;
        } else if (_inst.alarm.__yy_owner !== 1584050178) {
            _inst.alarm = _inst.alarm.slice(0);
            _inst.alarm.__yy_owner = 1584050178;
        }
        _inst.alarm[~~0] = 1;
        if (_inst.gmlbuttonPressed > 0.5) {
            {
                if (_inst.gmlstatus == 0) {
                    {
                        global.gmljoyJumpVal = _inst.gmlbutton;
                    }
                } else {
                    if (_inst.gmlstatus == 1) {
                        {
                            global.gmljoyAttackVal = _inst.gmlbutton;
                        }
                    } else {
                        if (_inst.gmlstatus == 2) {
                            {
                                global.gmljoyItemVal = _inst.gmlbutton;
                            }
                        } else {
                            if (_inst.gmlstatus == 3) {
                                {
                                    global.gmljoyRunVal = _inst.gmlbutton;
                                }
                            } else {
                                if (_inst.gmlstatus == 4) {
                                    {
                                        global.gmljoyBombVal = _inst.gmlbutton;
                                    }
                                } else {
                                    if (_inst.gmlstatus == 5) {
                                        {
                                            global.gmljoyRopeVal = _inst.gmlbutton;
                                        }
                                    } else {
                                        if (_inst.gmlstatus == 6) {
                                            {
                                                global.gmljoyPayVal = _inst.gmlbutton;
                                            }
                                        } else {
                                            if (_inst.gmlstatus == 7) {
                                                {
                                                    global.gmljoyStartVal = _inst.gmlbutton;
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        if (_inst.gmlbuttonPressed > 0.5 || keyboard_check_pressed(27) > 0.5) {
            {
                _inst.gmlstatus += 1;
                if (_inst.gmlstatus > 7) {
                    room_goto(5);
                }
            }
        }
    }
}

