function gml_Object_oLevelEditor_KeyPress_89(_inst, _other) {
    {
        if (_inst.gmlstatus == _inst.gmlEXIT || _inst.gmlstatus == _inst.gmlNEW) {
            {
                file_delete(_inst.gmllevelName);
                if (!(_inst.gmlexitNames instanceof Array)) {
                    _inst.gmlexitNames = [];
                    _inst.gmlexitNames.__yy_owner = 3373438787;
                } else if (_inst.gmlexitNames.__yy_owner !== 3373438787) {
                    _inst.gmlexitNames = _inst.gmlexitNames.slice(0);
                    _inst.gmlexitNames.__yy_owner = 3373438787;
                }
                _inst.gmlexitNames[~~0] = "";
                _inst.gmlexitNamesID = 0;
                if (!(_inst.gmlsignNames instanceof Array)) {
                    _inst.gmlsignNames = [];
                    _inst.gmlsignNames.__yy_owner = 2352384204;
                } else if (_inst.gmlsignNames.__yy_owner !== 2352384204) {
                    _inst.gmlsignNames = _inst.gmlsignNames.slice(0);
                    _inst.gmlsignNames.__yy_owner = 2352384204;
                }
                _inst.gmlsignNames[~~0] = "";
                _inst.gmlsignNamesID = 0;
                _inst.gmlfile = file_text_open_write(g_pBuiltIn.working_directory + "levels/" + string_lower(_inst.gmllevelName) + ".lvl");
                for (_inst.gmlj = 0; _inst.gmlj < 32; _inst.gmlj += 1) {
                    {
                        for (_inst.gmli = 0; _inst.gmli < 40; _inst.gmli += 1) {
                            {
                                file_text_write_string(_inst.gmlfile, _inst.gmllevelArray[~~_inst.gmli][~~_inst.gmlj]);
                                if (_inst.gmllevelArray[~~_inst.gmli][~~_inst.gmlj] == "X" || _inst.gmllevelArray[~~_inst.gmli][~~_inst.gmlj] == "@") {
                                    {
                                        _inst.gmlobj = instance_position(16 + _inst.gmli * 16, 16 + _inst.gmlj * 16, 99);
                                        if (!(_inst.gmlobj > 0.5)) {
                                            _inst.gmlobj = instance_position(16 + _inst.gmli * 16, 16 + _inst.gmlj * 16, 97);
                                        }
                                        if (_inst.gmlobj > 0.5) {
                                            {
                                                _inst.gmlexitNames[~~_inst.gmlexitNamesID] = yyInst(_inst.gmlobj).gmlleadsTo;
                                                _inst.gmlexitNamesID += 1;
                                            }
                                        }
                                    }
                                } else {
                                    if (_inst.gmllevelArray[~~_inst.gmli][~~_inst.gmlj] == "I") {
                                        {
                                            _inst.gmlobj = instance_position(16 + _inst.gmli * 16, 16 + _inst.gmlj * 16, 102);
                                            if (_inst.gmlobj > 0.5) {
                                                {
                                                    _inst.gmlsignNames[~~_inst.gmlsignNamesID] = yyInst(_inst.gmlobj).gmlmessage;
                                                    _inst.gmlsignNamesID += 1;
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        file_text_writeln(_inst.gmlfile);
                    }
                }
                file_text_write_string(_inst.gmlfile, _inst.gmlauthor);
                file_text_writeln(_inst.gmlfile);
                file_text_write_string(_inst.gmlfile, _inst.gmlmusic);
                file_text_writeln(_inst.gmlfile);
                file_text_write_string(_inst.gmlfile, _inst.gmllifeStart);
                file_text_writeln(_inst.gmlfile);
                file_text_write_string(_inst.gmlfile, _inst.gmlbombStart);
                file_text_writeln(_inst.gmlfile);
                file_text_write_string(_inst.gmlfile, _inst.gmlropeStart);
                file_text_writeln(_inst.gmlfile);
                file_text_write_string(_inst.gmlfile, _inst.gmlnextLevel);
                file_text_writeln(_inst.gmlfile);
                file_text_write_string(_inst.gmlfile, string(_inst.gmlexitNamesID));
                if (_inst.gmlexitNamesID > 0) {
                    file_text_writeln(_inst.gmlfile);
                }
                for (_inst.gmli = 0; _inst.gmli < _inst.gmlexitNamesID; _inst.gmli += 1) {
                    {
                        file_text_write_string(_inst.gmlfile, _inst.gmlexitNames[~~_inst.gmli]);
                        if (_inst.gmli < _inst.gmlexitNamesID) {
                            file_text_writeln(_inst.gmlfile);
                        }
                    }
                }
                file_text_write_string(_inst.gmlfile, string(_inst.gmlsignNamesID));
                if (_inst.gmlsignNamesID > 0) {
                    file_text_writeln(_inst.gmlfile);
                }
                for (_inst.gmli = 0; _inst.gmli < _inst.gmlsignNamesID; _inst.gmli += 1) {
                    {
                        file_text_write_string(_inst.gmlfile, _inst.gmlsignNames[~~_inst.gmli]);
                        if (_inst.gmli < _inst.gmlsignNamesID - 1) {
                            file_text_writeln(_inst.gmlfile);
                        }
                    }
                }
                file_text_close(_inst.gmlfile);
            }
        }
        if (_inst.gmlstatus == _inst.gmlEXIT) {
            {
                global.gmltitleStart = 2;
                if (file_exists(g_pBuiltIn.working_directory + "levels/test.tmp") > 0.5) {
                    file_delete(g_pBuiltIn.working_directory + "levels/test.tmp");
                }
                room_goto(5);
            }
        } else {
            if (_inst.gmlstatus == _inst.gmlNEW) {
                {
                    global.gmltestLevel = "";
                    room_restart();
                }
            }
        }
    }
}

