function gml_Object_oTransition_Draw_0(_inst, _other) {
    {
        if (global.gmlhtml5Build > 0.5) {
            {
                gml_Script_drawTouchControls(_inst, _other);
            }
        }
        draw_set_font(global.gmlfontSmall);
        draw_set_color(16777215);
        if (instance_exists(343) > 0.5) {
            {
                _inst.gmlperson = instance_nearest(_inst, 176, 176, 343);
                if (yyInst(_inst.gmlperson).gmltalk == 1) {
                    {
                        _inst.gmlstrLen = string_length(gml_Script_tr(_inst, _other, "HEY THERE! I'M THE TUNNEL MAN!")) * global.gmlfontSmallWidth;
                        _inst.gmln = 320 - _inst.gmlstrLen;
                        _inst.gmln = ceil(_inst.gmln / 2);
                        draw_text(_inst.gmln, 208, gml_Script_tr(_inst, _other, "HEY THERE! I'M THE TUNNEL MAN!"));
                        _inst.gmlstrLen = string_length(gml_Script_tr(_inst, _other, "I DIG SHORTCUTS.")) * global.gmlfontSmallWidth;
                        _inst.gmln = 320 - _inst.gmlstrLen;
                        _inst.gmln = ceil(_inst.gmln / 2);
                        draw_text(_inst.gmln, 216, gml_Script_tr(_inst, _other, "I DIG SHORTCUTS."));
                    }
                } else {
                    if (yyInst(_inst.gmlperson).gmltalk == 2) {
                        {
                            _inst.gmlstrLen = string_length(gml_Script_tr(_inst, _other, "CAN YOU LEND ME A LITTLE MONEY?")) * global.gmlfontSmallWidth;
                            _inst.gmln = 320 - _inst.gmlstrLen;
                            _inst.gmln = ceil(_inst.gmln / 2);
                            draw_text(_inst.gmln, 208, gml_Script_tr(_inst, _other, "CAN YOU LEND ME A LITTLE MONEY?"));
                            if (gml_Script_isRoom(_inst, _other, "rTransition1x") > 0.5 || gml_Script_isRoom(_inst, _other, "rTransition3x") > 0.5) {
                                _inst.gmlstrLen = string_length(gml_Script_tr(_inst, _other, "I NEED $") + string(global.gmltunnel1) + gml_Script_tr(_inst, _other, " FOR A NEW SHORTCUT.")) * global.gmlfontSmallWidth;
                            } else {
                                _inst.gmlstrLen = string_length(gml_Script_tr(_inst, _other, "I NEED $") + string(global.gmltunnel2) + gml_Script_tr(_inst, _other, " FOR A NEW SHORTCUT.")) * global.gmlfontSmallWidth;
                            }
                            _inst.gmln = 320 - _inst.gmlstrLen;
                            _inst.gmln = ceil(_inst.gmln / 2);
                            if (gml_Script_isRoom(_inst, _other, "rTransition1x") > 0.5 || gml_Script_isRoom(_inst, _other, "rTransition3x") > 0.5) {
                                draw_text(_inst.gmln, 216, gml_Script_tr(_inst, _other, "I NEED $") + string(global.gmltunnel1) + gml_Script_tr(_inst, _other, " FOR A NEW SHORTCUT."));
                            } else {
                                draw_text(_inst.gmln, 216, gml_Script_tr(_inst, _other, "I NEED $") + string(global.gmltunnel2) + gml_Script_tr(_inst, _other, " FOR A NEW SHORTCUT."));
                            }
                            draw_set_color(65535);
                            draw_text(_inst.gmln, 224, gml_Script_tr(_inst, _other, "DONATE: ") + string(yyInst(343).gmldonate));
                            draw_set_color(16777215);
                        }
                    } else {
                        if (yyInst(_inst.gmlperson).gmltalk == 3) {
                            {
                                _inst.gmlstrLen = string_length(gml_Script_tr(_inst, _other, "THANKS! YOU WON'T REGRET IT!")) * global.gmlfontSmallWidth;
                                _inst.gmln = 320 - _inst.gmlstrLen;
                                _inst.gmln = ceil(_inst.gmln / 2);
                                draw_text(_inst.gmln, 216, gml_Script_tr(_inst, _other, "THANKS! YOU WON'T REGRET IT!"));
                            }
                        } else {
                            if (yyInst(_inst.gmlperson).gmltalk == 4) {
                                {
                                    _inst.gmlstrLen = string_length(gml_Script_tr(_inst, _other, "I'LL NEVER GET THIS SHORTCUT BUILT!")) * global.gmlfontSmallWidth;
                                    _inst.gmln = 320 - _inst.gmlstrLen;
                                    _inst.gmln = ceil(_inst.gmln / 2);
                                    draw_text(_inst.gmln, 216, gml_Script_tr(_inst, _other, "I'LL NEVER GET THIS SHORTCUT BUILT!"));
                                }
                            } else {
                                if (yyInst(_inst.gmlperson).gmltalk == 5) {
                                    {
                                        _inst.gmlstrLen = string_length(gml_Script_tr(_inst, _other, "ONE SHORTCUT, COMING UP!")) * global.gmlfontSmallWidth;
                                        _inst.gmln = 320 - _inst.gmlstrLen;
                                        _inst.gmln = ceil(_inst.gmln / 2);
                                        draw_text(_inst.gmln, 216, gml_Script_tr(_inst, _other, "ONE SHORTCUT, COMING UP!"));
                                    }
                                }
                            }
                        }
                    }
                }
            }
        } else {
            if (instance_exists(340) > 0.5) {
                {
                    _inst.gmlperson = instance_nearest(_inst, 176, 176, 340);
                    if (yyInst(_inst.gmlperson).gmlkissed > 0.5) {
                        {
                            _inst.gmlstrLen = string_length(gml_Script_tr(_inst, _other, "MY HERO!")) * global.gmlfontSmallWidth;
                            _inst.gmln = 320 - _inst.gmlstrLen;
                            _inst.gmln = ceil(_inst.gmln / 2);
                            draw_text(_inst.gmln, 216, gml_Script_tr(_inst, _other, "MY HERO!"));
                        }
                    }
                }
            }
        }
        draw_set_color(65535);
        if (global.gmlcustomLevel > 0.5) {
            draw_text(32, 48, global.gmlcustomLevelName + gml_Script_tr(_inst, _other, " COMPLETED!"));
        } else {
            if (global.gmlcurrLevel - 1 < 1) {
                draw_text(32, 48, gml_Script_tr(_inst, _other, "TUTORIAL CAVE COMPLETED!"));
            } else {
                draw_text(32, 48, gml_Script_tr(_inst, _other, "LEVEL ") + string(global.gmlcurrLevel - 1) + gml_Script_tr(_inst, _other, " COMPLETED!"));
            }
        }
        draw_set_color(16777215);
        draw_text(32, 64, gml_Script_tr(_inst, _other, "TIME  = "));
        draw_text(32, 80, gml_Script_tr(_inst, _other, "LOOT  = "));
        draw_text(32, 96, gml_Script_tr(_inst, _other, "KILLS = "));
        draw_text(32, 112, gml_Script_tr(_inst, _other, "MONEY = "));
        if (_inst.gmldrawLoot >= 1 && !(_inst.gmlisLoot > 0.5)) {
            {
                draw_text(96, 80, gml_Script_tr(_inst, _other, "NONE"));
            }
        }
        if (_inst.gmldrawLoot > -2) {
            {
                _inst.gmls = global.gmlxtime;
                _inst.gmls = floor(_inst.gmls / 1000);
                _inst.gmlm = 0;
                while (_inst.gmls > 59) {
                    {
                        _inst.gmls -= 60;
                        _inst.gmlm += 1;
                    }
                }
                if (_inst.gmls <= 20) {
                    global.gmlnoDarkLevel = 1 ? 1 : 0;
                } else {
                    global.gmlnoDarkLevel = 0 ? 1 : 0;
                }
                _inst.gmls2 = global.gmltime;
                _inst.gmls2 = floor(_inst.gmls2 / 1000);
                _inst.gmlm2 = 0;
                while (_inst.gmls2 > 59) {
                    {
                        _inst.gmls2 -= 60;
                        _inst.gmlm2 += 1;
                    }
                }
                if (_inst.gmls < 10 && _inst.gmls2 < 10) {
                    draw_text(96, 64, string(_inst.gmlm) + ":0" + string(_inst.gmls) + " / " + string(_inst.gmlm2) + ":0" + string(_inst.gmls2));
                } else {
                    if (_inst.gmls < 10) {
                        draw_text(96, 64, string(_inst.gmlm) + ":0" + string(_inst.gmls) + " / " + string(_inst.gmlm2) + ":" + string(_inst.gmls2));
                    } else {
                        if (_inst.gmls2 < 10) {
                            draw_text(96, 64, string(_inst.gmlm) + ":" + string(_inst.gmls) + " / " + string(_inst.gmlm2) + ":0" + string(_inst.gmls2));
                        } else {
                            draw_text(96, 64, string(_inst.gmlm) + ":" + string(_inst.gmls) + " / " + string(_inst.gmlm2) + ":" + string(_inst.gmls2));
                        }
                    }
                }
            }
        }
        if (_inst.gmldrawLoot == 2) {
            {
                if (!(_inst.gmlisKills > 0.5)) {
                    {
                        draw_text(96, 96, gml_Script_tr(_inst, _other, "NONE"));
                    }
                }
                draw_text(96, 112, "$" + string(_inst.gmlmoneyCount) + " / $" + string(global.gmlmoney));
            }
        }
    }
}

