function gml_Object_oPressStart_Draw_0(_inst, _other) {
    {
        var gmltext = "";
        if (instance_exists(454) > 0.5) {
            {
                _inst.gmlplayer = instance_nearest(_inst, 0, 0, 454);
                if (yyInst(_inst.gmlplayer).x > _inst.gmlanchorX) {
                    {
                        if (!(_inst.gmlpressStartBlink > 0.5)) {
                            {
                                if (global.gmlgamepadOn > 0.5) {
                                    {
                                        gmltext = gml_Script_tr(_inst, _other, "PRESS START TO SHOW THE MENU");
                                    }
                                } else {
                                    {
                                        if (!(global.gmlmobileBuild > 0.5)) {
                                            {
                                                gmltext = gml_Script_tr(_inst, _other, "PRESS ESC TO SHOW THE MENU");
                                            }
                                        }
                                    }
                                }
                                draw_set_font(global.gmlfontSmall);
                                draw_set_color(16777215);
                                _inst.gmlstrLen = string_length(gmltext) * global.gmlfontSmallWidth;
                                _inst.gmlposX = _inst.gmlanchorX + ceil((g_pBuiltIn.view_wview[~~0] - _inst.gmlstrLen) / 2);
                                draw_text(_inst.gmlposX, 108, gmltext);
                            }
                        }
                    }
                }
            }
        }
    }
}

