function gml_Object_yyScreen_Step_1(_inst, _other) {
    {
        if (!(surface_exists(_inst.gmlsurf) > 0.5) || _inst.gmlsurf_width != g_pBuiltIn.view_wport[~~0] || _inst.gmlsurf_height != g_pBuiltIn.view_hport[~~0]) {
            {
                if (surface_exists(_inst.gmlsurf) > 0.5) {
                    {
                        surface_free(_inst.gmlsurf);
                        _inst.gmlsurf = -1;
                    }
                }
                _inst.gmlsurf_width = g_pBuiltIn.view_wport[~~0];
                _inst.gmlsurf_height = g_pBuiltIn.view_hport[~~0];
                _inst.gmlsurf = surface_create(_inst.gmlsurf_width, _inst.gmlsurf_height);
            }
        }
        g_pBuiltIn.view_surface_id[~~0] = _inst.gmlsurf;
    }
}

