function gml_Object_oDebug_Step_0(_inst, _other) {
    {
        if (keyboard_check_pressed(112) > 0.5) {
            {
                show_debug_message("///////////////////////////////////////////");
                show_debug_message("Windows:0");
                show_debug_message("Linux:6");
                show_debug_message("MacOSX:1");
                show_debug_message("Unknown:-1");
                show_debug_message("///////////////////////////////////////////");
                switch (g_pBuiltIn.get_os_type()) {
                    case 0:
                        show_debug_message("Running on Windows");
                        break;
                    case 6:
                        show_debug_message("Running on Linux");
                        break;
                }
                if (g_pBuiltIn.get_os_browser() == -1) {
                    {
                        show_debug_message("Not running in a browser");
                    }
                } else {
                    {
                        if (g_pBuiltIn.get_os_browser() == 3) {
                            {
                                show_debug_message("Running in Chrome");
                            }
                        } else {
                            if (g_pBuiltIn.get_os_browser() == 2) {
                                {
                                    show_debug_message("Running in Firefox");
                                }
                            } else {
                                if (g_pBuiltIn.get_os_browser() == 0) {
                                    {
                                        show_debug_message("Running in unknown browser");
                                    }
                                }
                            }
                        }
                    }
                }
                show_debug_message("///////////////////////////////////////////");
            }
        }
        if (keyboard_check_pressed(113) > 0.5) {
            {
                global.gmllevelIndex += 1;
                switch (global.gmllevelIndex) {
                    case 1: {
                        room_goto(17);
                        break;
                    }
                    case 2: {
                        global.gmlcurrLevel = 4;
                        room_goto(18);
                        break;
                    }
                    case 3: {
                        global.gmlcurrLevel = 9;
                        room_goto(19);
                        break;
                    }
                    case 4: {
                        global.gmlcurrLevel = 13;
                        room_goto(20);
                        break;
                    }
                    case 5: {
                        room_goto(21);
                        break;
                    }
                    case 6: {
                        room_goto(22);
                        break;
                    }
                    case 7: {
                        room_goto(23);
                        break;
                    }
                    case 8: {
                        global.gmlcurrLevel = 16;
                        room_goto(23);
                        break;
                    }
                    case 9: {
                        room_goto(7);
                        break;
                    }
                    case 10: {
                        room_goto(8);
                        break;
                    }
                    case 11: {
                        room_goto(9);
                        break;
                    }
                    case 12: {
                        room_goto(24);
                        break;
                    }
                    case 13: {
                        room_goto(27);
                        break;
                    }
                    case 14: {
                        global.gmllevelIndex = 0;
                        break;
                    }
                }
            }
        }
        if (keyboard_check_pressed(114) > 0.5) {
            {
                global.gmlplife = 99;
                global.gmltunnel1 = 0;
                global.gmltunnel2 = 0;
                global.gmlmoney = 200000;
                global.gmltime = 300;
                global.gmlkills = 200;
                global.gmldamsels = 10;
            }
        }
        if (keyboard_check_pressed(115) > 0.5) {
            {
                _inst.gmlitemsBundleIndex += 1;
                if (_inst.gmlitemsBundleIndex == 6) {
                    {
                        _inst.gmlitemsBundleIndex = 0;
                    }
                }
            }
        }
        if (keyboard_check_pressed(116) > 0.5) {
            {
                var gmlplayer = yyInst(433).gmlplayers[~~0];
                switch (_inst.gmlitemsBundleIndex) {
                    case 0: {
                        instance_create(yyInst(gmlplayer).x - 24, yyInst(gmlplayer).y, 72);
                        instance_create(yyInst(gmlplayer).x + 24, yyInst(gmlplayer).y, 166);
                        instance_create(yyInst(gmlplayer).x - 48, yyInst(gmlplayer).y, 164);
                        instance_create(yyInst(gmlplayer).x + 48, yyInst(gmlplayer).y, 158);
                        instance_create(yyInst(gmlplayer).x - 72, yyInst(gmlplayer).y, 339);
                        instance_create(yyInst(gmlplayer).x + 72, yyInst(gmlplayer).y, 159);
                        break;
                    }
                    case 1: {
                        instance_create(yyInst(gmlplayer).x - 24, yyInst(gmlplayer).y, 80);
                        instance_create(yyInst(gmlplayer).x + 24, yyInst(gmlplayer).y, 77);
                        instance_create(yyInst(gmlplayer).x - 48, yyInst(gmlplayer).y, 76);
                        instance_create(yyInst(gmlplayer).x + 48, yyInst(gmlplayer).y, 78);
                        instance_create(yyInst(gmlplayer).x - 72, yyInst(gmlplayer).y, 81);
                        instance_create(yyInst(gmlplayer).x + 72, yyInst(gmlplayer).y, 83);
                        break;
                    }
                    case 2: {
                        instance_create(yyInst(gmlplayer).x - 24, yyInst(gmlplayer).y, 177);
                        instance_create(yyInst(gmlplayer).x + 24, yyInst(gmlplayer).y, 178);
                        instance_create(yyInst(gmlplayer).x - 48, yyInst(gmlplayer).y, 169);
                        instance_create(yyInst(gmlplayer).x + 48, yyInst(gmlplayer).y, 170);
                        instance_create(yyInst(gmlplayer).x - 72, yyInst(gmlplayer).y, 172);
                        instance_create(yyInst(gmlplayer).x + 72, yyInst(gmlplayer).y, 180);
                        break;
                    }
                    case 3: {
                        instance_create(yyInst(gmlplayer).x - 24, yyInst(gmlplayer).y, 179);
                        instance_create(yyInst(gmlplayer).x + 24, yyInst(gmlplayer).y, 167);
                        instance_create(yyInst(gmlplayer).x - 48, yyInst(gmlplayer).y, 168);
                        instance_create(yyInst(gmlplayer).x + 48, yyInst(gmlplayer).y, 161);
                        instance_create(yyInst(gmlplayer).x - 72, yyInst(gmlplayer).y, 160);
                        instance_create(yyInst(gmlplayer).x + 72, yyInst(gmlplayer).y, 165);
                        break;
                    }
                    case 4: {
                        instance_create(yyInst(gmlplayer).x - 24, yyInst(gmlplayer).y, 173);
                        instance_create(yyInst(gmlplayer).x + 24, yyInst(gmlplayer).y, 176);
                        instance_create(yyInst(gmlplayer).x - 48, yyInst(gmlplayer).y, 174);
                        instance_create(yyInst(gmlplayer).x + 48, yyInst(gmlplayer).y, 82);
                        instance_create(yyInst(gmlplayer).x - 72, yyInst(gmlplayer).y, 79);
                        instance_create(yyInst(gmlplayer).x + 72, yyInst(gmlplayer).y, 175);
                        break;
                    }
                    case 5: {
                        instance_create(yyInst(gmlplayer).x - 24, yyInst(gmlplayer).y, 91);
                        instance_create(yyInst(gmlplayer).x + 24, yyInst(gmlplayer).y, 92);
                        instance_create(yyInst(gmlplayer).x - 48, yyInst(gmlplayer).y, 86);
                        instance_create(yyInst(gmlplayer).x + 48, yyInst(gmlplayer).y, 75);
                        instance_create(yyInst(gmlplayer).x - 72, yyInst(gmlplayer).y, 171);
                        _inst.gmlcaveman = instance_create(yyInst(gmlplayer).x + 72, yyInst(gmlplayer).y, 44);
                        yyInst(_inst.gmlcaveman).gmlhp = 0;
                        break;
                    }
                }
            }
        }
    }
}

